//! Color specifications and ANSI escape writing.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Black,
    Blue,
    Green,
    Red,
    Cyan,
    Magenta,
    Yellow,
    White,
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ColorSpec {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub intense: bool,
    pub underline: bool,
}

impl ColorSpec {
    pub fn is_none(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && !self.bold && !self.intense && !self.underline
    }

    /// Write the escape sequences that enable this spec.
    pub fn write_start(&self, out: &mut Vec<u8>) {
        out.extend_from_slice(b"\x1b[0m");
        if self.bold {
            out.extend_from_slice(b"\x1b[1m");
        }
        if self.underline {
            out.extend_from_slice(b"\x1b[4m");
        }
        if let Some(c) = self.fg {
            write_color(out, true, c, self.intense);
        }
        if let Some(c) = self.bg {
            write_color(out, false, c, self.intense);
        }
    }

    pub fn write_reset(out: &mut Vec<u8>) {
        out.extend_from_slice(b"\x1b[0m");
    }
}

fn write_color(out: &mut Vec<u8>, fg: bool, c: Color, intense: bool) {
    let base = if fg { 38 } else { 48 };
    if intense {
        let n: Option<u8> = match c {
            Color::Black => Some(8),
            Color::Red => Some(9),
            Color::Green => Some(10),
            Color::Yellow => Some(11),
            Color::Blue => Some(12),
            Color::Magenta => Some(13),
            Color::Cyan => Some(14),
            Color::White => Some(15),
            _ => None,
        };
        if let Some(n) = n {
            out.extend_from_slice(format!("\x1b[{};5;{}m", base, n).as_bytes());
            return;
        }
    }
    let off = if fg { 30 } else { 40 };
    let s = match c {
        Color::Black => format!("\x1b[{}m", off),
        Color::Red => format!("\x1b[{}m", off + 1),
        Color::Green => format!("\x1b[{}m", off + 2),
        Color::Yellow => format!("\x1b[{}m", off + 3),
        Color::Blue => format!("\x1b[{}m", off + 4),
        Color::Magenta => format!("\x1b[{}m", off + 5),
        Color::Cyan => format!("\x1b[{}m", off + 6),
        Color::White => format!("\x1b[{}m", off + 7),
        Color::Ansi256(n) => format!("\x1b[{};5;{}m", base, n),
        Color::Rgb(r, g, b) => format!("\x1b[{};2;{};{};{}m", base, r, g, b),
    };
    out.extend_from_slice(s.as_bytes());
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutType {
    Path,
    Line,
    Column,
    Match,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Style {
    Bold,
    NoBold,
    Intense,
    NoIntense,
    Underline,
    NoUnderline,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SpecValue {
    None,
    Fg(Color),
    Bg(Color),
    Style(Style),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct UserColorSpec {
    pub ty: OutType,
    pub value: SpecValue,
}

fn parse_color(s: &str) -> Result<Color, String> {
    let lower = s.to_lowercase();
    let c = match &*lower {
        "black" => Some(Color::Black),
        "blue" => Some(Color::Blue),
        "green" => Some(Color::Green),
        "red" => Some(Color::Red),
        "cyan" => Some(Color::Cyan),
        "magenta" => Some(Color::Magenta),
        "yellow" => Some(Color::Yellow),
        "white" => Some(Color::White),
        _ => None,
    };
    if let Some(c) = c {
        return Ok(c);
    }
    fn parse_number(s: &str) -> Option<u8> {
        if let Some(h) = s.strip_prefix("0x") {
            u8::from_str_radix(h, 16).ok()
        } else {
            u8::from_str_radix(s, 10).ok()
        }
    }
    let unrecognized = || {
        format!(
            "unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
            s
        )
    };
    let rgb_err = || {
        format!(
            "unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
            s
        )
    };
    let codes: Vec<&str> = s.split(',').collect();
    if codes.len() == 1 {
        if let Some(n) = parse_number(codes[0]) {
            Ok(Color::Ansi256(n))
        } else if s.chars().all(|c| c.is_ascii_hexdigit()) {
            Err(format!(
                "unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'",
                s
            ))
        } else {
            Err(unrecognized())
        }
    } else if codes.len() == 3 {
        let mut v = vec![];
        for code in codes {
            match parse_number(code) {
                Some(n) => v.push(n),
                None => return Err(rgb_err()),
            }
        }
        Ok(Color::Rgb(v[0], v[1], v[2]))
    } else if s.contains(',') {
        Err(rgb_err())
    } else {
        Err(unrecognized())
    }
}

impl UserColorSpec {
    pub fn parse(s: &str) -> Result<UserColorSpec, String> {
        let pieces: Vec<&str> = s.split(':').collect();
        let fmt_err = || {
            format!(
                "invalid color spec format: '{}'. Valid format is '(path|line|column|match):(fg|bg|style):(value)'.",
                s
            )
        };
        if pieces.len() <= 1 || pieces.len() > 3 {
            return Err(fmt_err());
        }
        let ty = match &*pieces[0].to_lowercase() {
            "path" => OutType::Path,
            "line" => OutType::Line,
            "column" => OutType::Column,
            "match" => OutType::Match,
            _ => {
                return Err(format!(
                    "unrecognized output type '{}'. Choose from: path, line, column, match.",
                    pieces[0]
                ))
            }
        };
        let spec_ty = pieces[1].to_lowercase();
        match &*spec_ty {
            "fg" | "bg" | "style" | "none" => {}
            _ => {
                return Err(format!(
                    "unrecognized spec type '{}'. Choose from: fg, bg, style, none.",
                    pieces[1]
                ))
            }
        }
        if spec_ty == "none" {
            return Ok(UserColorSpec { ty, value: SpecValue::None });
        }
        if pieces.len() < 3 {
            return Err(fmt_err());
        }
        let val = pieces[2];
        let value = match &*spec_ty {
            "fg" => SpecValue::Fg(parse_color(val)?),
            "bg" => SpecValue::Bg(parse_color(val)?),
            _ => {
                let st = match &*val.to_lowercase() {
                    "bold" => Style::Bold,
                    "nobold" => Style::NoBold,
                    "intense" => Style::Intense,
                    "nointense" => Style::NoIntense,
                    "underline" => Style::Underline,
                    "nounderline" => Style::NoUnderline,
                    _ => {
                        return Err(format!(
                            "unrecognized style attribute '{}'. Choose from: nobold, bold, nointense, intense, nounderline, underline.",
                            val
                        ))
                    }
                };
                SpecValue::Style(st)
            }
        };
        Ok(UserColorSpec { ty, value })
    }
}

#[derive(Clone, Debug)]
pub struct ColorSpecs {
    pub path: ColorSpec,
    pub line: ColorSpec,
    pub column: ColorSpec,
    pub matched: ColorSpec,
}

impl ColorSpecs {
    pub fn new(user: &[UserColorSpec]) -> ColorSpecs {
        let mut specs = ColorSpecs {
            path: ColorSpec { fg: Some(Color::Magenta), ..Default::default() },
            line: ColorSpec { fg: Some(Color::Green), ..Default::default() },
            column: ColorSpec::default(),
            matched: ColorSpec { fg: Some(Color::Red), bold: true, ..Default::default() },
        };
