                    Style::NoBold => spec.bold = false,
                    Style::Intense => spec.intense = true,
                    Style::NoIntense => spec.intense = false,
                    Style::Underline => spec.underline = true,
                    Style::NoUnderline => spec.underline = false,
                },
            }
        }
        specs
    }
}
