//! Assorted helpers.

use std::ffi::OsStr;

/// Unescape a string with the same rules ripgrep uses for separators.
pub fn unescape(s: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        let b = s[i];
        if b != b'\\' {
            out.push(b);
            i += 1;
            continue;
        }
        if i + 1 >= s.len() {
            out.push(b'\\');
            i += 1;
            continue;
        }
        let c = s[i + 1];
        match c {
            b'n' => {
                out.push(b'\n');
                i += 2;
            }
            b'r' => {
                out.push(b'\r');
                i += 2;
            }
            b't' => {
                out.push(b'\t');
                i += 2;
            }
            b'0' => {
                out.push(0);
                i += 2;
            }
            b'\\' => {
                out.push(b'\\');
                i += 2;
            }
            b'x' => {
                if i + 3 < s.len() + 0 && i + 3 <= s.len() - 1 + 1 {
                    // need two hex digits at i+2, i+3
                }
                if i + 3 < s.len() + 1 && i + 3 <= s.len() {
                    if i + 4 <= s.len() {
                        let h = &s[i + 2..i + 4];
                        if h.iter().all(|b| b.is_ascii_hexdigit()) {
                            let v = u8::from_str_radix(std::str::from_utf8(h).unwrap(), 16).unwrap();
                            out.push(v);
                            i += 4;
                            continue;
                        }
                    }
                }
                out.push(b'\\');
                out.push(b'x');
                i += 2;
            }
            _ => {
                out.push(b'\\');
                out.push(c);
                i += 2;
            }
        }
    }
    out
}

pub fn unescape_os(s: &OsStr) -> Vec<u8> {
    unescape(crate::flags::os_bytes(s))
}

/// Escape bytes in a way that is printable, similar to Rust's byte string
/// debug format. Used for some error messages.
pub fn escape_bytes(bytes: &[u8]) -> String {
    let mut s = String::new();
    let mut i = 0;
    while i < bytes.len() {
        match std::str::from_utf8(&bytes[i..]) {
            Ok(rest) => {
                for ch in rest.chars() {
                    escape_char(ch, &mut s);
                }
                break;
            }
            Err(e) => {
                let valid = e.valid_up_to();
                let rest = std::str::from_utf8(&bytes[i..i + valid]).unwrap();
                for ch in rest.chars() {
                    escape_char(ch, &mut s);
                }
                i += valid;
                let bad = e.error_len().unwrap_or(bytes.len() - i);
                for &b in &bytes[i..i + bad] {
                    s.push_str(&format!("\\x{:02X}", b));
                }
                i += bad;
            }
        }
    }
    s
}

fn escape_char(ch: char, s: &mut String) {
    match ch {
        '\\' => s.push_str("\\\\"),
        '\0' => s.push_str("\\0"),
        '\t' => s.push_str("\\t"),
        '\r' => s.push_str("\\r"),
        '\n' => s.push_str("\\n"),
        c if (c as u32) < 0x20 || c as u32 == 0x7F => s.push_str(&format!("\\x{:02X}", c as u32)),
        c => s.push(c),
    }
}
