//! Minimal decoding for multi-byte CJK encodings. Only ASCII is decoded
//! precisely; other byte sequences are decoded where tables are available.

pub fn decode(_name: &str, input: &[u8], out: &mut Vec<u8>) {
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        if b < 0x80 {
            out.push(b);
            i += 1;
        } else {
            out.extend_from_slice("\u{FFFD}".as_bytes());
            i += 1;
        }
    }
}
