        GlobOptions { case_insensitive: false, literal_separator: false, backslash_escape: true }
    }
}

#[derive(Clone, Debug)]
pub struct GlobError {
    pub glob: String,
    pub kind: String,
}

impl std::fmt::Display for GlobError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "error parsing glob '{}': {}", self.glob, self.kind)
    }
}

struct Parser<'a> {
    glob: &'a str,
    chars: std::iter::Peekable<std::str::Chars<'a>>,
    prev: Option<char>,
    cur: Option<char>,
    // stack of alternation groups; each group is a list of branches.
    // stack[0] is the top level with a single branch.
    stack: Vec<Vec<Vec<Token>>>,
    opts: GlobOptions,
}

impl<'a> Parser<'a> {
    fn error(&self, kind: &str) -> GlobError {
        GlobError { glob: self.glob.to_string(), kind: kind.to_string() }
    }

    fn bump(&mut self) -> Option<char> {
        self.prev = self.cur;
        self.cur = self.chars.next();
        self.cur
    }

    fn peek(&mut self) -> Option<char> {
        self.chars.peek().copied()
    }

    fn tokens(&mut self) -> &mut Vec<Token> {
        self.stack.last_mut().unwrap().last_mut().unwrap()
    }

    fn push_token(&mut self, t: Token) {
        self.tokens().push(t);
    }

    fn pop_token(&mut self) -> Option<Token> {
        self.tokens().pop()
    }

    fn have_tokens(&mut self) -> bool {
        !self.tokens().is_empty()
    }

    fn parse(mut self) -> Result<Vec<Token>, GlobError> {
        while let Some(c) = self.bump() {
            match c {
                '?' => self.push_token(Token::Any),
                '*' => self.parse_star()?,
                '[' => self.parse_class()?,
                '{' => {
                    if self.stack.len() > 1 {
                        return Err(self.error("nested alternate groups are not allowed"));
                    }
                    self.stack.push(vec![vec![]]);
                }
                '}' => {
                    if self.stack.len() <= 1 {
                        self.push_token(Token::Literal('}'));
                    } else {
                        let group = self.stack.pop().unwrap();
                        self.push_token(Token::Alternates(group));
                    }
                }
                ',' => {
                    if self.stack.len() <= 1 {
                        self.push_token(Token::Literal(','));
                    } else {
                        self.stack.last_mut().unwrap().push(vec![]);
                    }
                }
                '\\' if self.opts.backslash_escape => match self.bump() {
                    None => return Err(self.error("dangling '\\'")),
                    Some(c) => self.push_token(Token::Literal(c)),
                },
                c => self.push_token(Token::Literal(c)),
            }
        }
        if self.stack.len() > 1 {
            return Err(self.error(
                "unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)",
            ));
        }
        Ok(self.stack.pop().unwrap().pop().unwrap())
    }

    fn parse_star(&mut self) -> Result<(), GlobError> {
        let prev = self.prev;
        if self.peek() != Some('*') {
            self.push_token(Token::ZeroOrMore);
            return Ok(());
        }
        self.bump();
        if !self.have_tokens() {
            if !self.peek().map_or(true, |c| c == '/') {
                self.push_token(Token::ZeroOrMore);
                self.push_token(Token::ZeroOrMore);
            } else {
                self.push_token(Token::RecursivePrefix);
                self.bump();
            }
            return Ok(());
        }
        if !prev.map(|c| c == '/').unwrap_or(false) {
            if self.stack.len() <= 1 || (prev != Some(',') && prev != Some('{')) {
                self.push_token(Token::ZeroOrMore);
                self.push_token(Token::ZeroOrMore);
                return Ok(());
            }
        }
        let is_suffix = match self.peek() {
            None => true,
            Some(',') | Some('}') if self.stack.len() >= 2 => true,
            Some('/') => {
                self.bump();
                false
            }
            _ => {
                self.push_token(Token::ZeroOrMore);
                self.push_token(Token::ZeroOrMore);
                return Ok(());
            }
        };
        match self.pop_token() {
            Some(Token::RecursivePrefix) => self.push_token(Token::RecursivePrefix),
            Some(Token::RecursiveSuffix) => self.push_token(Token::RecursiveSuffix),
            _ => {
                if is_suffix {
                    self.push_token(Token::RecursiveSuffix);
                } else {
                    self.push_token(Token::RecursiveZeroOrMore);
                }
            }
        }
        Ok(())
    }

    fn parse_class(&mut self) -> Result<(), GlobError> {
        let mut ranges: Vec<(char, char)> = vec![];
        let negated = match self.peek() {
            Some('!') | Some('^') => {
                self.bump();
                true
            }
            _ => false,
        };
        let mut first = true;
        let mut in_range = false;
        loop {
            let c = match self.bump() {
                Some(c) => c,
                None => return Err(self.error("unclosed character class; missing ']'")),
            };
            match c {
                ']' => {
                    if first {
                        ranges.push((']', ']'));
                    } else {
                        break;
                    }
                }
                '-' => {
                    if first {
                        ranges.push(('-', '-'));
                    } else if in_range {
                        let r = ranges.last_mut().unwrap();
                        r.1 = '-';
                        if r.1 < r.0 {
                            let (a, b) = *r;
                            return Err(self.error(&format!("invalid range; '{}' > '{}'", a, b)));
                        }
                        in_range = false;
                    } else {
                        in_range = true;
                    }
                }
                c => {
                    if in_range {
                        let r = ranges.last_mut().unwrap();
                        r.1 = c;
                        if r.1 < r.0 {
                            let (a, b) = *r;
                            return Err(self.error(&format!("invalid range; '{}' > '{}'", a, b)));
                        }
                    } else {
                        ranges.push((c, c));
                    }
                    in_range = false;
                }
            }
            first = false;
        }
        if in_range {
            ranges.push(('-', '-'));
        }
        self.push_token(Token::Class { negated, ranges });
        Ok(())
    }
}

fn push_literal(re: &mut String, c: char) {
    if c.is_ascii() {
        let b = c as u8;
        if b.is_ascii_alphanumeric() || b == b'_' || b == b'/' || b == b' ' {
            re.push(c);
        } else {
            re.push_str(&format!("\\x{:02X}", b));
        }
    } else {
        let mut buf = [0u8; 4];
        for b in c.encode_utf8(&mut buf).bytes() {
            re.push_str(&format!("\\x{:02X}", b));
        }
    }
}

fn class_char(re: &mut String, c: char) {
    if c.is_ascii() && (c as u8).is_ascii_alphanumeric() {
        re.push(c);
    } else if c.is_ascii() {
        re.push_str(&format!("\\x{:02X}", c as u8));
    } else {
        re.push_str(&format!("\\x{{{:X}}}", c as u32));
    }
}

fn tokens_to_regex(tokens: &[Token], opts: &GlobOptions, re: &mut String) {
    for t in tokens {
        match t {
            Token::Literal(c) => push_literal(re, *c),
            Token::Any => {
                if opts.literal_separator {
                    re.push_str("[^/]");
                } else {
                    re.push_str("(?s-u:.)");
                }
            }
            Token::ZeroOrMore => {
