            Token::RecursiveSuffix => re.push_str("/(?s-u:.)*"),
            Token::RecursiveZeroOrMore => re.push_str("(?:/|/(?s-u:.)*/)"),
            Token::Class { negated, ranges } => {
                let unicode = ranges.iter().any(|&(a, b)| !a.is_ascii() || !b.is_ascii());
                if unicode {
                    re.push_str("(?u:");
                }
                re.push('[');
                if *negated {
                    re.push('^');
