//! Gitignore style matching, overrides (-g/--glob) and file types.

use std::path::{Path, PathBuf};

use crate::glob::{glob_to_regex, GlobError, GlobOptions, GlobSet};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Match {
    None,
    Ignore,
    Whitelist,
}

impl Match {
    pub fn is_none(&self) -> bool {
        *self == Match::None
    }
    pub fn is_ignore(&self) -> bool {
        *self == Match::Ignore
    }
    pub fn is_whitelist(&self) -> bool {
        *self == Match::Whitelist
    }
    pub fn invert(self) -> Match {
        match self {
            Match::None => Match::None,
            Match::Ignore => Match::Whitelist,
            Match::Whitelist => Match::Ignore,
        }
    }
    pub fn or(self, other: Match) -> Match {
        if self.is_none() {
            other
        } else {
            self
        }
    }
}

pub fn path_bytes(p: &Path) -> &[u8] {
    use std::os::unix::ffi::OsStrExt;
    p.as_os_str().as_bytes()
}

pub fn bytes_path(b: &[u8]) -> &Path {
    use std::os::unix::ffi::OsStrExt;
    Path::new(std::ffi::OsStr::from_bytes(b))
}

fn strip_prefix_bytes<'a>(prefix: &[u8], path: &'a [u8]) -> Option<&'a [u8]> {
    if prefix.len() > path.len() || &path[..prefix.len()] != prefix {
        None
    } else {
        Some(&path[prefix.len()..])
    }
}

#[derive(Clone, Debug)]
struct GiGlob {
    #[allow(dead_code)]
    original: String,
    whitelist: bool,
    only_dir: bool,
}

/// A compiled set of gitignore rules rooted at a directory.
pub struct Gitignore {
    root: Vec<u8>,
    globs: Vec<GiGlob>,
    set: GlobSet,
    num_ignores: usize,
    num_whitelists: usize,
}

impl Gitignore {
    pub fn empty() -> Gitignore {
        Gitignore { root: vec![], globs: vec![], set: GlobSet::empty(), num_ignores: 0, num_whitelists: 0 }
    }

    pub fn is_empty(&self) -> bool {
        self.globs.is_empty()
    }

    pub fn num_ignores(&self) -> usize {
        self.num_ignores
    }

    pub fn num_whitelists(&self) -> usize {
        self.num_whitelists
    }

    fn strip<'a>(&self, path: &'a [u8]) -> &'a [u8] {
        let mut path = path;
        if let Some(p) = strip_prefix_bytes(b"./", path) {
            path = p;
        }
        let is_file_name = !path.contains(&b'/');
        if self.root != b"." && !is_file_name {
            if let Some(p) = strip_prefix_bytes(&self.root, path) {
                path = p;
                if let Some(p) = strip_prefix_bytes(b"/", path) {
                    path = p;
                }
            }
        }
        path
    }

    pub fn matched(&self, path: &[u8], is_dir: bool) -> Match {
        if self.is_empty() {
            return Match::None;
        }
        let path = self.strip(path);
        let matches = self.set.matches(path);
        for &i in matches.iter().rev() {
            let g = &self.globs[i];
            if !g.only_dir || is_dir {
                return if g.whitelist { Match::Whitelist } else { Match::Ignore };
            }
        }
        Match::None
    }
}

pub struct GitignoreBuilder {
    root: Vec<u8>,
    globs: Vec<GiGlob>,
    regexes: Vec<String>,
    pub case_insensitive: bool,
}

impl GitignoreBuilder {
    pub fn new(root: &Path) -> GitignoreBuilder {
        let mut r = path_bytes(root);
        if let Some(p) = strip_prefix_bytes(b"./", r) {
            r = p;
        }
        GitignoreBuilder { root: r.to_vec(), globs: vec![], regexes: vec![], case_insensitive: false }
    }

    pub fn build(self) -> Gitignore {
        let num_ignores = self.globs.iter().filter(|g| !g.whitelist).count();
        let num_whitelists = self.globs.iter().filter(|g| g.whitelist).count();
        Gitignore {
            root: self.root,
            set: GlobSet::new(&self.regexes),
            globs: self.globs,
            num_ignores,
            num_whitelists,
        }
    }

    pub fn add_line(&mut self, line: &str) -> Result<(), GlobError> {
        if line.starts_with('#') {
            return Ok(());
        }
        let mut line: &str = line;
        if !line.ends_with("\\ ") {
            line = line.trim_end();
        }
        if line.is_empty() {
            return Ok(());
        }
        let original = line.to_string();
        let mut whitelist = false;
        let mut only_dir = false;
        let mut absolute = false;
        if line.starts_with("\\!") || line.starts_with("\\#") {
            line = &line[1..];
            absolute = line.starts_with('/');
        } else {
            if let Some(l) = line.strip_prefix('!') {
                whitelist = true;
                line = l;
            }
            if let Some(l) = line.strip_prefix('/') {
                line = l;
                absolute = true;
            }
        }
        if line.ends_with('/') {
            only_dir = true;
            line = &line[..line.len() - 1];
            if line.ends_with('\\') {
                line = &line[..line.len() - 1];
            }
        }
        let mut actual = line.to_string();
        if !absolute && !line.contains('/') {
            if !(actual.starts_with("**/") || actual == "**") {
                actual = format!("**/{}", actual);
            }
        }
        if actual.ends_with("/**") {
            actual.push_str("/*");
        }
        let opts = GlobOptions {
            case_insensitive: self.case_insensitive,
            literal_separator: true,
            backslash_escape: true,
        };
        let re = match glob_to_regex(&actual, opts) {
            Ok(re) => re,
            Err(e) => return Err(GlobError { glob: original, kind: e.kind }),
        };
        self.regexes.push(re);
        self.globs.push(GiGlob { original, whitelist, only_dir });
        Ok(())
    }

    /// Add all lines from the given file. Returns an error message for any
    /// problems found (if the file doesn't exist and `must_exist` is false,
    /// then nothing is reported).
    pub fn add_file(&mut self, path: &Path, must_exist: bool) -> Option<String> {
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(e) => {
                if !must_exist && e.kind() == std::io::ErrorKind::NotFound {
                    return None;
                }
                return Some(format!("{}: {}", path.display(), crate::util::io_err_string(&e)));
            }
        };
        let mut errs: Vec<String> = vec![];
        let mut lineno = 0;
        let mut rest: &[u8] = &data;
        while !rest.is_empty() {
            lineno += 1;
            let (line, next) = match memchr::memchr(b'\n', rest) {
                Some(i) => (&rest[..i], &rest[i + 1..]),
                None => (rest, &rest[rest.len()..]),
            };
            rest = next;
            let mut line = line;
            if line.ends_with(b"\r") {
                line = &line[..line.len() - 1];
            }
            let s = match std::str::from_utf8(line) {
                Ok(s) => s.to_string(),
                Err(_) => {
                    errs.push(format!(
                        "{}: line {}: {}",
                        path.display(),
                        lineno,
                        "stream did not contain valid UTF-8"
                    ));
                    break;
                }
            };
            let s = if lineno == 1 { s.trim_start_matches('\u{feff}').to_string() } else { s };
            if let Err(e) = self.add_line(&s) {
                errs.push(format!("{}: line {}: {}", path.display(), lineno, e));
            }
        }
        if errs.is_empty() {
            None
        } else {
            Some(errs.join("\n"))
        }
    }
}

// ---------------------------------------------------------------------------
// Overrides

pub struct Override {
    gi: Gitignore,
}

impl Override {
    pub fn empty() -> Override {
        Override { gi: Gitignore::empty() }
    }

    pub fn build(
        root: &Path,
        globs: &[String],
        iglobs: &[String],
        case_insensitive: bool,
    ) -> Result<Override, GlobError> {
        let mut b = GitignoreBuilder::new(root);
        b.case_insensitive = case_insensitive;
        for g in globs {
            b.add_line(g)?;
        }
        b.case_insensitive = true;
        for g in iglobs {
            b.add_line(g)?;
        }
        Ok(Override { gi: b.build() })
    }

    pub fn is_empty(&self) -> bool {
        self.gi.is_empty()
    }

    pub fn matched(&self, path: &[u8], is_dir: bool) -> Match {
        if self.is_empty() {
            return Match::None;
        }
        let m = self.gi.matched(path, is_dir).invert();
        if m.is_none() && self.gi.num_ignores() > 0 && !is_dir {
            return Match::Ignore;
        }
        m
    }
}

// ---------------------------------------------------------------------------
// File types

#[derive(Clone, Debug)]
pub struct TypeDef {
    pub name: String,
    pub globs: Vec<String>,
}

pub struct TypesBuilder {
    types: std::collections::BTreeMap<String, TypeDef>,
    selections: Vec<(bool, String)>,
}

pub fn invalid_def() -> String {
    "invalid definition (format is type:glob, e.g., html:*.html)".to_string()
}

impl TypesBuilder {
    pub fn new() -> TypesBuilder {
        TypesBuilder { types: Default::default(), selections: vec![] }
    }

    pub fn add_defaults(&mut self) {
        for (name, globs) in crate::default_types::DEFAULT_TYPES {
            for g in globs.iter() {
                let _ = self.add(name, g);
            }
        }
    }

    pub fn add(&mut self, name: &str, glob: &str) -> Result<(), String> {
        if name == "all" || !name.chars().all(|c| c.is_alphanumeric()) {
            return Err(invalid_def());
        }
        self.types
            .entry(name.to_string())
            .or_insert_with(|| TypeDef { name: name.to_string(), globs: vec![] })
            .globs
            .push(glob.to_string());
        Ok(())
    }

    pub fn clear(&mut self, name: &str) {
        self.types.remove(name);
    }

    pub fn select(&mut self, name: &str) {
        self.selections.push((false, name.to_string()));
    }

    pub fn negate(&mut self, name: &str) {
        self.selections.push((true, name.to_string()));
    }

    pub fn add_def(&mut self, def: &str) -> Result<(), String> {
        let parts: Vec<&str> = def.split(':').collect();
        match parts.len() {
            2 => {
                let (name, glob) = (parts[0], parts[1]);
                if name.is_empty() || glob.is_empty() {
                    return Err(invalid_def());
                }
                self.add(name, glob)
            }
            3 => {
                let (name, types) = (parts[0], parts[2]);
                if name.is_empty() || parts[1] != "include" || types.is_empty() {
                    return Err(invalid_def());
                }
                if types.split(',').any(|t| !self.types.contains_key(t)) {
                    return Err(invalid_def());
                }
                for t in types.split(',') {
                    let globs = self.types.get(t).unwrap().globs.clone();
                    for g in globs {
                        self.add(name, &g)?;
                    }
                }
                Ok(())
            }
            _ => Err(invalid_def()),
        }
    }

    /// Return all definitions sorted by name, with sorted globs.
    pub fn definitions(&self) -> Vec<TypeDef> {
        let mut defs: Vec<TypeDef> = self.types.values().cloned().collect();
        for d in defs.iter_mut() {
            d.globs.sort();
        }
        defs
    }

    pub fn build(&self) -> Result<Types, String> {
        let mut regexes = vec![];
        let mut glob_sel: Vec<bool> = vec![];
        let mut has_selected = false;
        for (negated, name) in &self.selections {
            if !negated {
                has_selected = true;
            }
            let defs: Vec<&TypeDef> = if name == "all" {
                self.types.values().collect()
            } else {
                match self.types.get(name) {
                    Some(d) => vec![d],
                    None => return Err(format!("unrecognized file type: {}", name)),
                }
            };
            for def in defs {
                for g in &def.globs {
                    let re = glob_to_regex(g, GlobOptions::default()).map_err(|e| e.to_string())?;
                    regexes.push(re);
                    glob_sel.push(*negated);
                }
            }
        }
        Ok(Types {
            set: GlobSet::new(&regexes),
            glob_negated: glob_sel,
            has_selected,
            empty: self.selections.is_empty(),
        })
    }
}

pub struct Types {
    set: GlobSet,
    glob_negated: Vec<bool>,
    has_selected: bool,
    empty: bool,
}

impl Types {
    pub fn empty() -> Types {
        Types { set: GlobSet::empty(), glob_negated: vec![], has_selected: false, empty: true }
    }

    pub fn is_empty(&self) -> bool {
        self.empty
    }

    pub fn matched(&self, path: &[u8], is_dir: bool) -> Match {
        if is_dir || self.empty {
            return Match::None;
        }
        let name = match path.iter().rposition(|&b| b == b'/') {
            Some(i) => &path[i + 1..],
            None => path,
        };
        if name.is_empty() || name == b".." || name == b"." {
            return if self.has_selected { Match::Ignore } else { Match::None };
        }
        let matches = self.set.matches(name);
        if let Some(&i) = matches.last() {
            return if self.glob_negated[i] { Match::Ignore } else { Match::Whitelist };
        }
        if self.has_selected {
            Match::Ignore
        } else {
            Match::None
        }
    }
}

