#[derive(Clone, Debug)]
pub struct IgnoreOpts {
    pub hidden: bool,
    pub ignore: bool,
    pub parents: bool,
    pub git_global: bool,
    pub git_ignore: bool,
    pub git_exclude: bool,
    pub require_git: bool,
    pub case_insensitive: bool,
    pub custom_names: Vec<String>,
}

pub struct Shared {
    pub opts: IgnoreOpts,
    pub overrides: Override,
    pub types: Types,
    pub global: Gitignore,
    pub explicit: Vec<Gitignore>,
}

pub struct IgnoreDir {
    pub dir: PathBuf,
    pub parent: Option<std::rc::Rc<IgnoreDir>>,
    pub is_absolute_parent: bool,
    pub absolute_base: Option<std::rc::Rc<PathBuf>>,
    custom: Gitignore,
    ignore: Gitignore,
    git: Gitignore,
    git_exclude: Gitignore,
    pub has_git: bool,
}

fn resolve_git_dir(dir: &Path) -> Option<PathBuf> {
    let git = dir.join(".git");
    let md = std::fs::metadata(&git).ok()?;
    if md.is_dir() {
        return Some(git);
    }
    // A .git file pointing to the real git dir.
    let data = std::fs::read_to_string(&git).ok()?;
    let line = data.lines().next()?;
    let p = line.strip_prefix("gitdir:")?.trim();
    let p = PathBuf::from(p);
    let p = if p.is_absolute() { p } else { dir.join(p) };
    // Handle worktrees with a commondir file.
    if let Ok(cd) = std::fs::read_to_string(p.join("commondir")) {
        let cd = PathBuf::from(cd.trim());
        let cd = if cd.is_absolute() { cd } else { p.join(cd) };
        return Some(cd);
    }
    Some(p)
}

impl IgnoreDir {
    fn load(shared: &Shared, dir: &Path, errs: &mut Vec<String>) -> IgnoreDir {
        let opts = &shared.opts;
        let has_git = if opts.require_git && opts.git_ignore {
            std::fs::symlink_metadata(dir.join(".git")).is_ok()
        } else {
            false
        };
        let load_names = |names: &[&str], errs: &mut Vec<String>| -> Gitignore {
            let mut b = GitignoreBuilder::new(dir);
            b.case_insensitive = opts.case_insensitive;
            let mut any = false;
            for name in names {
                let p = dir.join(name);
                if let Some(e) = b.add_file(&p, false) {
                    errs.push(e);
                }
                any = true;
            }
            if !any {
                return Gitignore::empty();
            }
            b.build()
        };
        let custom = if opts.ignore && !opts.custom_names.is_empty() {
            let names: Vec<&str> = opts.custom_names.iter().map(|s| s.as_str()).collect();
            load_names(&names, errs)
        } else {
            Gitignore::empty()
        };
        let ignore = if opts.ignore { load_names(&[".ignore"], errs) } else { Gitignore::empty() };
        let git = if opts.git_ignore { load_names(&[".gitignore"], errs) } else { Gitignore::empty() };
        let git_exclude = if opts.git_exclude {
            match resolve_git_dir(dir) {
                Some(gd) => {
                    let mut b = GitignoreBuilder::new(dir);
                    b.case_insensitive = opts.case_insensitive;
                    if let Some(e) = b.add_file(&gd.join("info").join("exclude"), false) {
                        errs.push(e);
                    }
                    b.build()
                }
                None => Gitignore::empty(),
            }
        } else {
            Gitignore::empty()
        };
        IgnoreDir {
            dir: dir.to_path_buf(),
            parent: None,
            is_absolute_parent: false,
            absolute_base: None,
            custom,
            ignore,
            git,
            git_exclude,
            has_git,
        }
    }

    /// Create the root matcher for the given search root (a directory),
    /// including any applicable parent directories.
    pub fn root(shared: &Shared, root: &Path, errs: &mut Vec<String>) -> std::rc::Rc<IgnoreDir> {
        let opts = &shared.opts;
        let mut parent: Option<std::rc::Rc<IgnoreDir>> = None;
        let mut absolute_base = None;
        if opts.parents || opts.git_ignore || opts.git_exclude || opts.git_global {
            if let Ok(abs) = std::fs::canonicalize(root) {
                let abs = std::rc::Rc::new(abs);
                absolute_base = Some(abs.clone());
                let mut parents: Vec<PathBuf> = vec![];
                let mut p: &Path = &abs;
                while let Some(pp) = p.parent() {
                    parents.push(pp.to_path_buf());
                    p = pp;
                }
                for pdir in parents.into_iter().rev() {
                    let mut node = IgnoreDir::load(shared, &pdir, errs);
                    node.is_absolute_parent = true;
                    node.absolute_base = Some(abs.clone());
                    node.parent = parent.take();
                    parent = Some(std::rc::Rc::new(node));
                }
            }
        }
        let mut node = IgnoreDir::load(shared, root, errs);
        node.parent = parent;
        node.absolute_base = absolute_base;
        std::rc::Rc::new(node)
    }

    pub fn child(self: &std::rc::Rc<IgnoreDir>, shared: &Shared, dir: &Path, errs: &mut Vec<String>) -> std::rc::Rc<IgnoreDir> {
        let mut node = IgnoreDir::load(shared, dir, errs);
        node.parent = Some(self.clone());
        node.absolute_base = self.absolute_base.clone();
        std::rc::Rc::new(node)
    }

    fn chain(&self) -> Vec<&IgnoreDir> {
        let mut v = vec![self];
        let mut cur = self;
        while let Some(ref p) = cur.parent {
            v.push(p);
            cur = p;
        }
        v
    }

    fn has_any_ignore_rules(&self, shared: &Shared) -> bool {
        // We always evaluate; this is a cheap approximation.
        let _ = shared;
        true
    }

    /// Determine whether the given path (contained in this directory) should
    /// be ignored.
    pub fn matched(&self, shared: &Shared, path: &[u8], is_dir: bool) -> Match {
        let mut path = path;
        if let Some(p) = strip_prefix_bytes(b"./", path) {
            path = p;
        }
        if !shared.overrides.is_empty() {
            let m = shared.overrides.matched(path, is_dir);
            if !m.is_none() {
                return m;
            }
        }
        let mut whitelisted = Match::None;
        if self.has_any_ignore_rules(shared) {
            let m = self.matched_ignore(shared, path, is_dir);
            if m.is_ignore() {
                return m;
            } else if m.is_whitelist() {
                whitelisted = m;
            }
        }
        if !shared.types.is_empty() {
            let m = shared.types.matched(path, is_dir);
            if m.is_ignore() {
                return m;
            } else if m.is_whitelist() {
                whitelisted = m;
            }
        }
        if whitelisted.is_none() && shared.opts.hidden && is_hidden(path) {
            return Match::Ignore;
        }
        whitelisted
    }

    fn matched_ignore(&self, shared: &Shared, path: &[u8], is_dir: bool) -> Match {
        let opts = &shared.opts;
        let chain = self.chain();
        let (mut m_custom, mut m_ignore, mut m_gi, mut m_gi_exclude, mut m_explicit) =
            (Match::None, Match::None, Match::None, Match::None, Match::None);
        let any_git = !opts.require_git || chain.iter().any(|ig| ig.has_git);
        let mut saw_git = false;
        for ig in chain.iter().take_while(|ig| !ig.is_absolute_parent) {
            if m_custom.is_none() {
                m_custom = ig.custom.matched(path, is_dir);
            }
            if m_ignore.is_none() {
                m_ignore = ig.ignore.matched(path, is_dir);
            }
            if any_git && !saw_git && m_gi.is_none() {
                m_gi = ig.git.matched(path, is_dir);
            }
            if any_git && !saw_git && m_gi_exclude.is_none() {
                m_gi_exclude = ig.git_exclude.matched(path, is_dir);
            }
            saw_git = saw_git || ig.has_git;
        }
        if opts.parents {
            if let Some(ref abs) = self.absolute_base {
                let dirpath = path_bytes(&self.dir);
                let prefix = strip_prefix_bytes(b"./", dirpath).unwrap_or(dirpath);
                let joined = match strip_prefix_bytes(prefix, path) {
                    None => abs.join(bytes_path(path)),
                    Some(p) => {
                        let p = strip_prefix_bytes(b"/", p).unwrap_or(p);
                        abs.join(bytes_path(p))
                    }
                };
                let jp = path_bytes(&joined);
                for ig in chain.iter().skip_while(|ig| !ig.is_absolute_parent) {
                    if m_custom.is_none() {
                        m_custom = ig.custom.matched(jp, is_dir);
                    }
                    if m_ignore.is_none() {
                        m_ignore = ig.ignore.matched(jp, is_dir);
                    }
                    if any_git && !saw_git && m_gi.is_none() {
                        m_gi = ig.git.matched(jp, is_dir);
                    }
                    if any_git && !saw_git && m_gi_exclude.is_none() {
                        m_gi_exclude = ig.git_exclude.matched(jp, is_dir);
                    }
                    saw_git = saw_git || ig.has_git;
                }
            }
        }
        for gi in shared.explicit.iter().rev() {
            if !m_explicit.is_none() {
                break;
            }
            m_explicit = gi.matched(path, is_dir);
        }
        let m_global = if any_git { shared.global.matched(path, is_dir) } else { Match::None };
        m_custom.or(m_ignore).or(m_gi).or(m_gi_exclude).or(m_global).or(m_explicit)
    }
}

pub fn is_hidden(path: &[u8]) -> bool {
    let name = match path.iter().rposition(|&b| b == b'/') {
        Some(i) => &path[i + 1..],
        None => path,
    };
    name.first() == Some(&b'.')
}

/// Find the global gitignore file path, if any.
pub fn global_gitignore_path() -> Option<PathBuf> {
    fn home() -> Option<PathBuf> {
        std::env::var_os("HOME").filter(|h| !h.is_empty()).map(PathBuf::from)
    }
    fn xdg_config() -> Option<PathBuf> {
        match std::env::var_os("XDG_CONFIG_HOME").filter(|h| !h.is_empty()) {
            Some(x) => Some(PathBuf::from(x)),
            None => home().map(|h| h.join(".config")),
        }
    }
    // Look for core.excludesFile in git config files.
    let mut candidates = vec![];
    if let Some(x) = xdg_config() {
        candidates.push(x.join("git").join("config"));
    }
    if let Some(h) = home() {
        candidates.push(h.join(".gitconfig"));
    }
    let mut found: Option<PathBuf> = None;
    for c in candidates {
        if let Ok(data) = std::fs::read(&c) {
            if let Some(p) = parse_excludes_file(&data) {
                found = Some(p);
            }
        }
    }
    if let Some(p) = found {
        return Some(p);
    }
    xdg_config().map(|x| x.join("git").join("ignore"))
}

fn parse_excludes_file(data: &[u8]) -> Option<PathBuf> {
    let s = String::from_utf8_lossy(data);
    let mut in_core = false;
    let mut result = None;
    for line in s.lines() {
        let l = line.trim();
        if l.starts_with('[') {
            let sec = l.trim_start_matches('[').trim_end_matches(']').trim().to_ascii_lowercase();
            in_core = sec == "core";
            continue;
        }
        if !in_core {
            continue;
        }
        if let Some(eq) = l.find('=') {
            let key = l[..eq].trim().to_ascii_lowercase();
            if key == "excludesfile" {
                let mut v = l[eq + 1..].trim().to_string();
                if v.starts_with('"') && v.ends_with('"') && v.len() >= 2 {
                    v = v[1..v.len() - 1].to_string();
                }
                if let Some(rest) = v.strip_prefix("~/") {
                    if let Some(h) = std::env::var_os("HOME") {
                        result = Some(PathBuf::from(h).join(rest));
                        continue;
                    }
                }
                result = Some(PathBuf::from(v));
            }
        }
    }
    result
}
