#[derive(Default)]
struct Analysis {
    any_uppercase: bool,
    any_literal: bool,
}

impl Analysis {
    fn done(&self) -> bool {
        self.any_uppercase && self.any_literal
    }
    fn ast(&mut self, a: &ast::Ast) {
        if self.done() {
            return;
        }
        match a {
            ast::Ast::Literal(x) => self.lit(x),
            ast::Ast::ClassBracketed(x) => self.class_set(&x.kind),
            ast::Ast::Repetition(x) => self.ast(&x.ast),
            ast::Ast::Group(x) => self.ast(&x.ast),
            ast::Ast::Alternation(x) => {
                for a in &x.asts {
                    self.ast(a);
                }
            }
            ast::Ast::Concat(x) => {
                for a in &x.asts {
                    self.ast(a);
                }
            }
            _ => {}
        }
    }
    fn class_set(&mut self, s: &ast::ClassSet) {
        if self.done() {
            return;
        }
        match s {
            ast::ClassSet::Item(item) => self.class_item(item),
            ast::ClassSet::BinaryOp(op) => {
                self.class_set(&op.lhs);
                self.class_set(&op.rhs);
            }
        }
    }
    fn class_item(&mut self, item: &ast::ClassSetItem) {
        if self.done() {
            return;
        }
        match item {
            ast::ClassSetItem::Literal(x) => self.lit(x),
            ast::ClassSetItem::Range(x) => {
                self.lit(&x.start);
                self.lit(&x.end);
            }
            ast::ClassSetItem::Bracketed(x) => self.class_set(&x.kind),
            ast::ClassSetItem::Union(u) => {
                for i in &u.items {
                    self.class_item(i);
                }
            }
            _ => {}
        }
    }
    fn lit(&mut self, x: &ast::Literal) {
        if x.c.is_uppercase() {
            self.any_uppercase = true;
        }
        self.any_literal = true;
    }
}

fn byte_escape(b: u8) -> String {
    match b {
        b'\n' => "\\n".to_string(),
        b'\r' => "\\r".to_string(),
        b'\t' => "\\t".to_string(),
        0 => "\\0".to_string(),
        b'\\' => "\\\\".to_string(),
        b'"' => "\\\"".to_string(),
        b if b.is_ascii_graphic() || b == b' ' => (b as char).to_string(),
        b => format!("\\x{:02X}", b),
    }
}

/// Remove line terminators from classes and report literals containing them.
fn strip_line_term(h: Hir, bytes: &[u8]) -> Result<Hir, u8> {
    match h.into_kind() {
        HirKind::Empty => Ok(Hir::empty()),
        HirKind::Literal(hir::Literal(lit)) => {
            for &b in lit.iter() {
                if bytes.contains(&b) {
                    return Err(b);
                }
            }
            Ok(Hir::literal(lit))
        }
        HirKind::Class(Class::Unicode(mut cls)) => {
            for &b in bytes {
                let c = b as char;
                let rm = hir::ClassUnicode::new(vec![hir::ClassUnicodeRange::new(c, c)]);
                cls.difference(&rm);
            }
            Ok(Hir::class(Class::Unicode(cls)))
        }
        HirKind::Class(Class::Bytes(mut cls)) => {
            for &b in bytes {
                let rm = hir::ClassBytes::new(vec![hir::ClassBytesRange::new(b, b)]);
                cls.difference(&rm);
            }
            Ok(Hir::class(Class::Bytes(cls)))
        }
        HirKind::Look(l) => Ok(Hir::look(l)),
        HirKind::Repetition(mut rep) => {
            let sub = std::mem::replace(&mut rep.sub, Box::new(Hir::empty()));
            rep.sub = Box::new(strip_line_term(*sub, bytes)?);
            Ok(Hir::repetition(rep))
        }
        HirKind::Capture(mut cap) => {
            let sub = std::mem::replace(&mut cap.sub, Box::new(Hir::empty()));
            cap.sub = Box::new(strip_line_term(*sub, bytes)?);
            Ok(Hir::capture(cap))
        }
        HirKind::Concat(subs) => {
            let mut out = vec![];
            for s in subs {
                out.push(strip_line_term(s, bytes)?);
            }
            Ok(Hir::concat(out))
        }
        HirKind::Alternation(subs) => {
            let mut out = vec![];
            for s in subs {
                out.push(strip_line_term(s, bytes)?);
            }
            Ok(Hir::alternation(out))
        }
    }
}

/// Compute whether the given byte can never be part of a match.
fn can_match_byte(h: &Hir, b: u8) -> bool {
    match h.kind() {
        HirKind::Empty => false,
        HirKind::Look(l) => match l {
            Look::Start | Look::End | Look::StartLF | Look::EndLF => b == b'\n',
            Look::StartCRLF | Look::EndCRLF => b == b'\n' || b == b'\r',
            _ => false,
        },
        HirKind::Literal(hir::Literal(lit)) => lit.contains(&b),
        HirKind::Class(Class::Unicode(cls)) => {
            if b < 0x80 {
                cls.ranges().iter().any(|r| (r.start() as u32) <= b as u32 && b as u32 <= (r.end() as u32))
            } else {
                // Any non-ASCII codepoint's UTF-8 encoding might contain the byte.
                cls.ranges().iter().any(|r| (r.end() as u32) >= 0x80)
            }
        }
        HirKind::Class(Class::Bytes(cls)) => cls.ranges().iter().any(|r| r.start() <= b && b <= r.end()),
        HirKind::Repetition(rep) => can_match_byte(&rep.sub, b),
        HirKind::Capture(cap) => can_match_byte(&cap.sub, b),
        HirKind::Concat(subs) | HirKind::Alternation(subs) => subs.iter().any(|s| can_match_byte(s, b)),
    }
}

pub enum BuildError {
    Msg(String),
}

impl Matcher {
    pub fn new(patterns: &[String], cfg: &MatcherConfig) -> Result<Matcher, BuildError> {
        let pats: Vec<String> = if cfg.fixed_strings {
            patterns.iter().map(|p| regex_syntax::escape(p)).collect()
        } else {
            patterns.to_vec()
        };
        let joined = pats.iter().map(|p| format!("(?:{})", p)).collect::<Vec<_>>().join("|");
        let ast = ast::parse::ParserBuilder::new()
            .nest_limit(250)
            .octal(false)
            .ignore_whitespace(false)
            .build()
            .parse(&joined)
            .map_err(|e| BuildError::Msg(regex_syntax::Error::from(e).to_string()))?;
        let mut case_insensitive = cfg.case_insensitive;
        if cfg.smart_case {
            let mut an = Analysis::default();
            an.ast(&ast);
            case_insensitive = an.any_literal && !an.any_uppercase;
        }
        let mut tb = hir::translate::TranslatorBuilder::new();
        tb.utf8(false)
            .case_insensitive(case_insensitive)
            .multi_line(true)
            .dot_matches_new_line(cfg.dot_matches_new_line)
            .crlf(cfg.crlf)
            .swap_greed(false)
            .unicode(cfg.unicode);
        if let Some(lt) = cfg.line_terminator {
            tb.line_terminator(lt);
        }
        let mut hir = tb
            .build()
            .translate(&joined, &ast)
            .map_err(|e| BuildError::Msg(regex_syntax::Error::from(e).to_string()))?;
        if let Some(lt) = cfg.line_terminator {
            let bytes: Vec<u8> = if cfg.crlf { vec![b'\r', b'\n'] } else { vec![lt] };
            hir = strip_line_term(hir, &bytes).map_err(|b| {
                BuildError::Msg(format!(
                    "the literal \"{}\" is not allowed in a regex\n\nConsider enabling multiline mode with the --multiline flag (or -U for short).\nWhen multiline mode is enabled, new line characters can be matched.",
                    byte_escape(b)
                ))
            })?;
        }
        if cfg.line {
            let (s, e) = if cfg.crlf { (Look::StartCRLF, Look::EndCRLF) } else { (Look::StartLF, Look::EndLF) };
            hir = Hir::concat(vec![Hir::look(s), hir, Hir::look(e)]);
        } else if cfg.word {
            let (s, e) = if cfg.unicode {
                (Look::WordStartHalfUnicode, Look::WordEndHalfUnicode)
            } else {
                (Look::WordStartHalfAscii, Look::WordEndHalfAscii)
            };
            hir = Hir::concat(vec![Hir::look(s), hir, Hir::look(e)]);
        }
        let lt = cfg.line_terminator.unwrap_or(b'\n');
        let never_matches_line_term = !can_match_byte(&hir, lt);
        let mut mc = meta::Config::new().utf8_empty(false);
        mc = mc.nfa_size_limit(Some(cfg.size_limit.unwrap_or(100 * (1 << 20))));
        mc = mc.dfa_size_limit(Some(cfg.dfa_size_limit.unwrap_or(1000 * (1 << 20))));
        mc = mc.hybrid_cache_capacity(cfg.dfa_size_limit.unwrap_or(1000 * (1 << 20)));
        if let Some(lt) = cfg.line_terminator {
            mc = mc.line_terminator(lt);
        }
        let re = meta::Builder::new().configure(mc).build_from_hir(&hir).map_err(|e| {
            if let Some(limit) = e.size_limit() {
                BuildError::Msg(format!("compiled regex exceeds size limit of {}", limit))
            } else if let Some(se) = e.syntax_error() {
                BuildError::Msg(se.to_string())
            } else {
                BuildError::Msg(e.to_string())
            }
        })?;
        let mut names = vec![];
        for (i, n) in re.group_info().pattern_names(regex_automata::PatternID::ZERO).enumerate() {
            if let Some(n) = n {
                names.push((n.to_string(), i));
            }
        }
        Ok(Matcher { re, never_matches_line_term, names })
    }

    /// Does the regex match anywhere in the given haystack (searched in
    /// isolation)?
    pub fn is_match(&self, hay: &[u8]) -> bool {
        self.re.is_match(Input::new(hay))
    }

    /// Find the leftmost match in hay[at..], with look-around able to see
    /// the full haystack.
    pub fn find_at(&self, hay: &[u8], at: usize) -> Option<(usize, usize)> {
        if at > hay.len() {
            return None;
        }
        let input = Input::new(hay).span(at..hay.len());
        self.re.search(&input).map(|m| (m.start(), m.end()))
    }

    /// Iterate over successive non-overlapping matches starting at `at`.
    pub fn find_iter_at<F: FnMut(usize, usize) -> bool>(&self, hay: &[u8], at: usize, mut f: F) {
        let mut last_end = at;
        let mut last_match: Option<usize> = None;
        loop {
            if last_end > hay.len() {
                return;
            }
            let (s, e) = match self.find_at(hay, last_end) {
                None => return,
                Some(m) => m,
            };
            if s == e {
                last_end = e + 1;
                if Some(e) == last_match {
                    continue;
                }
            } else {
                last_end = e;
            }
            last_match = Some(e);
            if !f(s, e) {
                return;
            }
        }
    }

    pub fn create_captures(&self) -> Captures {
        self.re.create_captures()
    }

    pub fn captures_at(&self, hay: &[u8], at: usize, caps: &mut Captures) -> bool {
        if at > hay.len() {
            return false;
        }
        let input = Input::new(hay).span(at..hay.len());
        self.re.search_captures(&input, caps);
        caps.is_match()
    }

    pub fn capture_index(&self, name: &str) -> Option<usize> {
        self.names.iter().find(|(n, _)| n == name).map(|(_, i)| *i)
    }

    /// Iterate over captures of successive matches starting at `at`.
    pub fn captures_iter_at<F: FnMut(&Captures) -> bool>(&self, hay: &[u8], at: usize, mut f: F) {
        let mut caps = self.create_captures();
        let mut last_end = at;
        let mut last_match: Option<usize> = None;
        loop {
            if last_end > hay.len() {
                return;
            }
            if !self.captures_at(hay, last_end, &mut caps) {
                return;
            }
            let m = caps.get_match().unwrap();
            let (s, e) = (m.start(), m.end());
            if s == e {
                last_end = e + 1;
                if Some(e) == last_match {
                    continue;
                }
            } else {
                last_end = e;
            }
            last_match = Some(e);
            if !f(&caps) {
                return;
            }
        }
    }
}

/// Interpolate a replacement string using the given captures.
pub fn interpolate(
    matcher: &Matcher,
    caps: &Captures,
    subject: &[u8],
    mut replacement: &[u8],
    dst: &mut Vec<u8>,
) {
    fn valid(b: u8) -> bool {
        b.is_ascii_alphanumeric() || b == b'_'
    }
    while !replacement.is_empty() {
        match memchr::memchr(b'$', replacement) {
            None => break,
            Some(i) => {
                dst.extend_from_slice(&replacement[..i]);
                replacement = &replacement[i..];
            }
        }
        if replacement.get(1) == Some(&b'$') {
            dst.push(b'$');
            replacement = &replacement[2..];
            continue;
        }
        // find cap ref
        let rep = replacement;
        let parsed = (|| {
            if rep.len() <= 1 || rep[0] != b'$' {
                return None;
            }
            let mut i = 1;
            let mut brace = false;
            if rep[i] == b'{' {
                brace = true;
                i += 1;
            }
            let mut end = i;
            while end < rep.len() && valid(rep[end]) {
                end += 1;
            }
            if end == i {
                return None;
            }
            let name = std::str::from_utf8(&rep[i..end]).unwrap().to_string();
            if brace {
                if rep.get(end) != Some(&b'}') {
                    return None;
                }
                end += 1;
            }
            Some((name, end))
        })();
        match parsed {
            None => {
                dst.push(b'$');
                replacement = &replacement[1..];
            }
            Some((name, end)) => {
                replacement = &replacement[end..];
                let idx = match name.parse::<u32>() {
                    Ok(n) => Some(n as usize),
                    Err(_) => matcher.capture_index(&name),
                };
                if let Some(idx) = idx {
                    if let Some(sp) = caps.get_group(idx) {
                        dst.extend_from_slice(&subject[sp.start..sp.end]);
                    }
                }
            }
        }
    }
    dst.extend_from_slice(replacement);
}
