cat > /workspace/src/searcher.rs <<'EOF'
//! Line oriented searching over in-memory buffers.

use crate::matcher::Matcher;

pub const BUFFER_CAPACITY: usize = 64 * 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BinaryDetection {
    None,
    Quit(u8),
    Convert(u8),
}

impl BinaryDetection {
    pub fn is_quit(&self) -> bool {
        matches!(self, BinaryDetection::Quit(_))
    }
    pub fn is_convert(&self) -> bool {
        matches!(self, BinaryDetection::Convert(_))
    }
    pub fn byte(&self) -> Option<u8> {
        match *self {
            BinaryDetection::None => None,
            BinaryDetection::Quit(b) | BinaryDetection::Convert(b) => Some(b),
        }
    }
}

#[derive(Clone, Debug)]
pub struct SearcherConfig {
    pub line_term: u8,
    pub crlf: bool,
    pub invert: bool,
    pub before: usize,
    pub after: usize,
    pub passthru: bool,
    pub stop_on_nonmatch: bool,
    pub multi_line: bool,
    pub binary: BinaryDetection,
    pub line_number: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ContextKind {
    Before,
    After,
    Other,
}

pub struct SinkMatch<'a> {
    pub buffer: &'a [u8],
    pub start: usize,
    pub end: usize,
    pub line_number: Option<u64>,
    pub absolute_byte_offset: u64,
}

impl<'a> SinkMatch<'a> {
    pub fn bytes(&self) -> &'a [u8] {
        &self.buffer[self.start..self.end]
    }
}

pub struct SinkContext<'a> {
    pub bytes: &'a [u8],
    pub kind: ContextKind,
    pub line_number: Option<u64>,
    pub absolute_byte_offset: u64,
}

pub trait Sink {
    fn begin(&mut self, _s: &Searcher) -> bool {
        true
    }
    fn matched(&mut self, s: &Searcher, m: &SinkMatch) -> bool;
    fn context(&mut self, s: &Searcher, c: &SinkContext) -> bool;
    fn context_break(&mut self, s: &Searcher) -> bool;
    fn binary_data(&mut self, _s: &Searcher, _offset: u64) -> bool {
        true
    }
    fn finish(&mut self, s: &Searcher, byte_count: u64, binary_offset: Option<u64>);
}

pub struct Searcher<'m> {
    pub cfg: SearcherConfig,
    pub matcher: &'m Matcher,
}

struct Core<'s, 'm, S: Sink> {
    searcher: &'s Searcher<'m>,
    sink: &'s mut S,
    pos: usize,
    last_line_visited: usize,
    after_context_left: usize,
    has_sunk: bool,
    has_matched: bool,
    line_number: u64,
    last_line_counted: usize,
    binary_byte_offset: Option<usize>,
    /// Whether to perform binary detection on each sunk line (slice mode).
    binary: bool,
}

impl<'s, 'm, S: Sink> Core<'s, 'm, S> {
    fn new(searcher: &'s Searcher<'m>, sink: &'s mut S, binary: bool) -> Self {
        Core {
            searcher,
            sink,
            pos: 0,
            last_line_visited: 0,
            after_context_left: 0,
            has_sunk: false,
            has_matched: false,
            line_number: 1,
            last_line_counted: 0,
            binary_byte_offset: None,
            binary,
        }
    }

    fn cfg(&self) -> &SearcherConfig {
        &self.searcher.cfg
    }

    fn count_lines(&mut self, buf: &[u8], upto: usize) {
        if !self.cfg().line_number {
            return;
        }
        if self.last_line_counted >= upto {
            return;
        }
        let lt = self.cfg().line_term;
        let n = memchr::memchr_iter(lt, &buf[self.last_line_counted..upto]).count();
        self.line_number += n as u64;
        self.last_line_counted = upto;
    }

    fn line_number(&self) -> Option<u64> {
        if self.cfg().line_number {
            Some(self.line_number)
        } else {
            None
        }
    }

    /// Returns true if searching should stop.
    fn detect_binary(&mut self, buf: &[u8], start: usize, end: usize) -> bool {
        if self.binary_byte_offset.is_some() {
            return self.cfg().binary.is_quit();
        }
        let b = match self.cfg().binary.byte() {
            None => return false,
            Some(b) => b,
        };
        if let Some(i) = memchr::memchr(b, &buf[start..end]) {
            let offset = start + i;
            self.binary_byte_offset = Some(offset);
            if !self.sink.binary_data(self.searcher, offset as u64) {
                return true;
            }
            self.cfg().binary.is_quit()
        } else {
            false
        }
    }

    fn sink_break_context(&mut self, start_of_line: usize) -> bool {
        let is_gap = self.last_line_visited < start_of_line;
        let any_context = self.cfg().before > 0 || self.cfg().after > 0;
        if !any_context || !self.has_sunk || !is_gap {
            true
        } else {
            self.sink.context_break(self.searcher)
        }
    }

    fn sink_matched(&mut self, buf: &[u8], start: usize, end: usize) -> bool {
        if self.binary && self.detect_binary(buf, start, end) {
            return false;
        }
        if !self.sink_break_context(start) {
            return false;
        }
        self.count_lines(buf, start);
        let m = SinkMatch {
            buffer: buf,
            start,
            end,
            line_number: self.line_number(),
            absolute_byte_offset: start as u64,
        };
        if !self.sink.matched(self.searcher, &m) {
            return false;
        }
        self.last_line_visited = end;
        self.after_context_left = self.cfg().after;
        self.has_sunk = true;
        true
    }

    fn sink_context(&mut self, buf: &[u8], start: usize, end: usize, kind: ContextKind) -> bool {
        if self.binary && self.detect_binary(buf, start, end) {
            return false;
        }
        self.count_lines(buf, start);
        let c = SinkContext {
            bytes: &buf[start..end],
            kind,
            line_number: self.line_number(),
            absolute_byte_offset: start as u64,
        };
        if !self.sink.context(self.searcher, &c) {
            return false;
        }
        self.last_line_visited = end;
        if kind == ContextKind::After {
            self.after_context_left -= 1;
        }
        self.has_sunk = true;
        true
    }

    fn before_context_by_line(&mut self, buf: &[u8], upto: usize) -> bool {
        let before = self.cfg().before;
        if before == 0 {
            return true;
        }
        let rstart = self.last_line_visited;
        if rstart >= upto {
            return true;
        }
        // Find the start of the `before`th line preceding upto.
        let lt = self.cfg().line_term;
        let mut start = upto;
        let mut count = 0;
        while start > rstart && count < before {
            // move to the start of the previous line
            let mut p = start - 1; // this is the terminator of the previous line
            loop {
                if p == rstart {
                    start = rstart;
                    break;
                }
                if buf[p - 1] == lt {
                    start = p;
                    break;
                }
                p -= 1;
            }
            count += 1;
        }
        let mut s = start;
        while s < upto {
            let e = match memchr::memchr(lt, &buf[s..upto]) {
                Some(i) => s + i + 1,
                None => upto,
            };
            if !self.sink_break_context(s) {
                return false;
            }
            if !self.sink_context(buf, s, e, ContextKind::Before) {
                return false;
            }
            s = e;
        }
        true
    }

    fn after_context_by_line(&mut self, buf: &[u8], upto: usize) -> bool {
        if self.after_context_left == 0 {
            return true;
        }
        let lt = self.cfg().line_term;
        let mut s = self.last_line_visited;
        while s < upto {
            let e = match memchr::memchr(lt, &buf[s..upto]) {
                Some(i) => s + i + 1,
                None => upto,
            };
            if !self.sink_context(buf, s, e, ContextKind::After) {
                return false;
            }
            if self.after_context_left == 0 {
                break;
            }
            s = e;
        }
        true
    }

    fn other_context_by_line(&mut self, buf: &[u8], upto: usize) -> bool {
        let lt = self.cfg().line_term;
        let mut s = self.last_line_visited;
        while s < upto {
            let e = match memchr::memchr(lt, &buf[s..upto]) {
                Some(i) => s + i + 1,
                None => upto,
            };
            if !self.sink_context(buf, s, e, ContextKind::Other) {
                return false;
            }
            s = e;
        }
        true
    }

    fn without_terminator<'b>(&self, line: &'b [u8]) -> &'b [u8] {
        let lt = self.cfg().line_term;
        let mut l = line;
        if l.last() == Some(&lt) {
            l = &l[..l.len() - 1];
            if self.cfg().crlf && l.last() == Some(&b'\r') {
                l = &l[..l.len() - 1];
            }
        }
        l
    }

    /// Search lines in buf[pos..end]. Returns false if searching should stop.
    /// `binary_notify` is an absolute position at which the sink should be
    /// told about binary data (read mode, convert).
    fn match_by_line(&mut self, buf: &[u8], end: usize, notify: &mut Option<(usize, usize)>) -> bool {
        let lt = self.cfg().line_term;
        while self.pos < end {
            let start = self.pos;
            if let Some((cut, off)) = *notify {
                if start >= cut {
                    *notify = None;
                    self.binary_byte_offset = Some(off);
                    if !self.sink.binary_data(self.searcher, off as u64) {
                        return false;
                    }
                }
            }
            let line_end = match memchr::memchr(lt, &buf[start..end]) {
                Some(i) => start + i + 1,
                None => end,
            };
            let slice = self.without_terminator(&buf[start..line_end]);
            let matched = self.searcher.matcher.is_match(slice);
            self.pos = line_end;
            let success = matched != self.cfg().invert;
            if success {
                self.has_matched = true;
                if !self.before_context_by_line(buf, start) {
                    return false;
                }
                if !self.sink_matched(buf, start, line_end) {
                    return false;
                }
            } else if self.after_context_left >= 1 {
                if !self.sink_context(buf, start, line_end, ContextKind::After) {
                    return false;
                }
            } else if self.cfg().passthru {
                if !self.sink_context(buf, start, line_end, ContextKind::Other) {
                    return false;
                }
            }
            if self.cfg().stop_on_nonmatch && !success && self.has_matched {
                return false;
            }
        }
        true
    }
}

fn locate(bytes: &[u8], lt: u8, start: usize, end: usize) -> (usize, usize) {
    let line_start = match memchr::memrchr(lt, &bytes[..start]) {
        Some(i) => i + 1,
        None => 0,
    };
    let line_end = if end > line_start && bytes[end - 1] == lt {
        end
    } else {
        match memchr::memchr(lt, &bytes[end..]) {
            Some(i) => end + i + 1,
            None => bytes.len(),
        }
    };
    (line_start, line_end)
}

/// Simulate the read buffer to determine where binary data is first
/// observed. Returns (cut, nul_offset) where `cut` is the position up to
/// which data was searched before binary data was detected.
fn simulate_fills(data: &[u8], lt: u8, byte: u8, max_context: usize) -> Option<(usize, usize)> {
    let nul = memchr::memchr(byte, data)?;
    let mut cap = BUFFER_CAPACITY;
    let mut buf_start = 0usize;
    let mut buf_end = 0usize;
    let mut last_lineterm = 0usize;
    loop {
        // roll
        let consumed_upto = if max_context == 0 {
            last_lineterm
        } else {
            // keep the last max_context lines of buf_start..last_lineterm
            let mut p = last_lineterm;
            let mut count = 0;
            while p > buf_start && count < max_context {
                let mut q = p - 1;
                while q > buf_start && data[q - 1] != lt {
                    q -= 1;
                }
                p = q;
                count += 1;
            }
            p
        };
        buf_start = consumed_upto.max(buf_start);
        loop {
            if buf_end - buf_start >= cap {
                cap *= 3;
            }
            let free = cap - (buf_end - buf_start);
            let n = std::cmp::min(free, data.len() - buf_end);
            if n == 0 {
                return None;
            }
            let (s, e) = (buf_end, buf_end + n);
            if nul >= s && nul < e {
                return Some((last_lineterm, nul));
            }
            buf_end = e;
            if let Some(i) = memchr::memrchr(lt, &data[s..e]) {
                last_lineterm = s + i + 1;
                break;
            }
        }
    }
}

impl<'m> Searcher<'m> {
    pub fn new(cfg: SearcherConfig, matcher: &'m Matcher) -> Searcher<'m> {
        Searcher { cfg, matcher }
    }

    /// Search a buffer as if it were memory mapped (or read entirely on to
    /// the heap).
    pub fn search_slice<S: Sink>(&self, data: &[u8], sink: &mut S) {
        let mut core = Core::new(self, sink, true);
        if !core.sink.begin(self) {
            core.sink.finish(self, 0, None);
            return;
        }
        let binary_upto = std::cmp::min(data.len(), BUFFER_CAPACITY);
        if self.cfg.multi_line {
            if !core.detect_binary(data, 0, binary_upto) {
                multi_line_run(&mut core, data);
            }
        } else if !core.detect_binary(data, 0, binary_upto) {
            let mut notify = None;
            core.match_by_line(data, data.len(), &mut notify);
        }
        let pos = core.pos as u64;
        let byte_count = match core.binary_byte_offset {
            Some(off) if (off as u64) < pos => off as u64,
            _ => pos,
        };
        let bo = core.binary_byte_offset.map(|o| o as u64);
        let searcher = core.searcher;
        core.sink.finish(searcher, byte_count, bo);
    }

    /// Search a buffer as if it were read incrementally.
    pub fn search_read<S: Sink>(&self, mut data: Vec<u8>, sink: &mut S) {
        if self.cfg.multi_line {
            return self.search_slice(&data, sink);
        }
        let max_context = std::cmp::max(self.cfg.before, self.cfg.after);
        let lt = self.cfg.line_term;
        let mut notify: Option<(usize, usize)> = None;
        let mut end = data.len();
        let mut quit_binary: Option<usize> = None;
        match self.cfg.binary {
            BinaryDetection::None => {}
            BinaryDetection::Quit(b) => {
                if let Some((cut, off)) = simulate_fills(&data, lt, b, max_context) {
                    end = cut;
                    quit_binary = Some(off);
                }
            }
            BinaryDetection::Convert(b) => {
                if let Some((cut, off)) = simulate_fills(&data, lt, b, max_context) {
                    notify = Some((cut, off));
                    if b != lt {
                        for x in data.iter_mut() {
                            if *x == b {
                                *x = lt;
                            }
                        }
                    }
                }
            }
        }
        let mut core = Core::new(self, sink, false);
        if !core.sink.begin(self) {
            core.sink.finish(self, 0, None);
            return;
        }
        let mut keepgoing = core.match_by_line(&data, end, &mut notify);
        if keepgoing {
            if let Some(off) = quit_binary {
                core.binary_byte_offset = Some(off);
                core.sink.binary_data(self, off as u64);
                keepgoing = false;
            }
        }
        let _ = keepgoing;
        if let Some((_, off)) = notify {
            // binary data was seen but never reported because we stopped
            // before reaching it; ripgrep would still have detected it if
            // the data had been read. Only report if we got there.
            let _ = off;
        }
        let byte_count = if quit_binary.is_some() { end as u64 } else { core.pos as u64 };
        let bo = core.binary_byte_offset.map(|o| o as u64);
        let searcher = core.searcher;
        core.sink.finish(searcher, byte_count, bo);
    }
}

fn multi_line_run<S: Sink>(core: &mut Core<S>, slice: &[u8]) {
    let lt = core.cfg().line_term;
    let mut last_match: Option<(usize, usize)> = None;
    let mut keepgoing = true;

    fn find<S: Sink>(core: &Core<S>, slice: &[u8]) -> Option<(usize, usize)> {
        let pos = core.pos;
        core.searcher.matcher.find_at(&slice[pos..], 0).map(|(s, e)| (s + pos, e + pos))
    }
    fn advance<S: Sink>(core: &mut Core<S>, s: usize, e: usize) {
        if s == e {
            core.pos = e + 1;
        } else {
            core.pos = e;
        }
    }
    fn sink_context<S: Sink>(core: &mut Core<S>, slice: &[u8], start: usize) -> bool {
        if core.cfg().passthru {
            core.other_context_by_line(slice, start)
        } else {
            if !core.after_context_by_line(slice, start) {
                return false;
            }
            core.before_context_by_line(slice, start)
        }
    }
    fn sink_matched<S: Sink>(core: &mut Core<S>, slice: &[u8], s: usize, e: usize) -> bool {
        if s == e {
            return false;
        }
        core.sink_matched(slice, s, e)
    }

    while core.pos < slice.len() && keepgoing {
        if core.cfg().invert {
            // inverted
            let (rs, re) = match find(core, slice) {
                None => {
                    let r = (core.pos, slice.len());
                    core.pos = slice.len();
                    r
                }
                Some((s, e)) => {
                    let (ls, le) = locate(slice, lt, s, e);
                    let r = (core.pos, ls);
                    advance(core, ls, le);
                    r
                }
            };
            if rs >= re {
                continue;
            }
            if !sink_context(core, slice, rs) {
                keepgoing = false;
                break;
            }
            let mut p = rs;
            while p < re {
                let e = match memchr::memchr(lt, &slice[p..re]) {
                    Some(i) => p + i + 1,
                    None => re,
                };
                if !sink_matched(core, slice, p, e) {
                    keepgoing = false;
                    break;
                }
                p = e;
            }
            continue;
        }
        let (ms, me) = match find(core, slice) {
            Some(m) => m,
            None => {
                core.pos = slice.len();
                break;
            }
        };
        advance(core, ms, me);
        let line = locate(slice, lt, ms, me);
        match last_match.take() {
            None => last_match = Some(line),
            Some(lm) => {
                if lm.1 >= line.0 {
                    last_match = Some((lm.0, line.1));
                } else {
                    last_match = Some(line);
                    if !sink_context(core, slice, lm.0) {
                        keepgoing = false;
                        break;
                    }
                    if !sink_matched(core, slice, lm.0, lm.1) {
                        keepgoing = false;
                        break;
                    }
                }
            }
        }
    }
    if keepgoing {
        if let Some(lm) = last_match.take() {
            keepgoing = sink_context(core, slice, lm.0) && sink_matched(core, slice, lm.0, lm.1);
        }
    }
    if keepgoing {
        if core.cfg().passthru {
            core.other_context_by_line(slice, slice.len());
        } else {
            core.after_context_by_line(slice, slice.len());
        }
    }
}
