//! Output printers: standard, summary and JSON.

use std::time::{Duration, Instant};

use bstr::ByteSlice;

use crate::color::{ColorSpec, ColorSpecs};
use crate::matcher::{interpolate, Matcher};
use crate::searcher::{ContextKind, Searcher, Sink, SinkContext, SinkMatch};

pub const MAX_LOOK_AHEAD: usize = 128;

#[derive(Clone, Debug, Default)]
pub struct Stats {
    pub elapsed: Duration,
    pub searches: u64,
    pub searches_with_match: u64,
    pub bytes_searched: u64,
    pub bytes_printed: u64,
    pub matched_lines: u64,
    pub matches: u64,
}

impl Stats {
    pub fn add(&mut self, o: &Stats) {
        self.elapsed += o.elapsed;
        self.searches += o.searches;
        self.searches_with_match += o.searches_with_match;
        self.bytes_searched += o.bytes_searched;
        self.bytes_printed += o.bytes_printed;
        self.matched_lines += o.matched_lines;
        self.matches += o.matches;
    }
}

pub fn fractional_seconds(d: Duration) -> f64 {
    (d.as_secs() as f64) + (d.subsec_nanos() as f64 * 1e-9)
}

/// Output writer that tracks whether colors are enabled.
pub struct Out<'a> {
    pub buf: &'a mut Vec<u8>,
    pub color: bool,
    pub start_len: usize,
}

impl<'a> Out<'a> {
    pub fn count(&self) -> usize {
        self.buf.len() - self.start_len
    }
    pub fn write(&mut self, b: &[u8]) {
        self.buf.extend_from_slice(b);
    }
    pub fn write_spec(&mut self, spec: &ColorSpec, b: &[u8]) {
        if self.color {
            spec.write_start(self.buf);
            self.buf.extend_from_slice(b);
            ColorSpec::write_reset(self.buf);
        } else {
            self.buf.extend_from_slice(b);
        }
    }
}

/// Information about how to print paths.
#[derive(Clone)]
pub struct PathPrinter {
    pub separator: Option<u8>,
    pub hyperlink: Option<crate::hyperlink::HyperlinkConfig>,
}

impl PathPrinter {
    pub fn display(&self, path: &[u8]) -> Vec<u8> {
        match self.separator {
            None => path.to_vec(),
            Some(sep) => path.iter().map(|&b| if b == b'/' { sep } else { b }).collect(),
        }
    }
}

#[derive(Clone)]
pub struct StandardConfig {
    pub colors: ColorSpecs,
    pub heading: bool,
    pub path: bool,
    pub only_matching: bool,
    pub per_match: bool,
    pub per_match_one_line: bool,
    pub replacement: Option<Vec<u8>>,
    pub max_columns: Option<u64>,
    pub max_columns_preview: bool,
    pub max_matches: Option<u64>,
    pub column: bool,
    pub byte_offset: bool,
    pub trim_ascii: bool,
    pub separator_search: Option<Vec<u8>>,
    pub separator_context: Option<Vec<u8>>,
    pub separator_field_match: Vec<u8>,
    pub separator_field_context: Vec<u8>,
    pub path_terminator: Option<u8>,
    pub line_number: bool,
    pub stats: bool,
}

/// Find matches in the given bytes, in the same way ripgrep's printer does.
pub fn find_iter_at_in_context<F: FnMut(usize, usize) -> bool>(
    searcher: &Searcher,
    matcher: &Matcher,
    bytes: &[u8],
    start: usize,
    end: usize,
    mut f: F,
) {
    let hay: &[u8] = if searcher.cfg.multi_line {
        let e = std::cmp::min(bytes.len(), end.saturating_add(MAX_LOOK_AHEAD));
        &bytes[..e]
    } else {
        let e = trim_line_terminator_end(searcher, bytes, 0, end);
        &bytes[..e]
    };
    matcher.find_iter_at(hay, start, |s, e| {
        if s >= end {
            return false;
        }
        f(s, e)
    });
}

/// Return the end of the range after trimming a line terminator.
pub fn trim_line_terminator_end(searcher: &Searcher, bytes: &[u8], start: usize, end: usize) -> usize {
    let lt = searcher.cfg.line_term;
    let mut e = end;
    if e > start && bytes[e - 1] == lt {
        e -= 1;
        if searcher.cfg.crlf && e > start && bytes[e - 1] == b'\r' {
            e -= 1;
        }
    }
    e
}

fn line_term_bytes(searcher: &Searcher) -> &'static [u8] {
    if searcher.cfg.crlf {
        b"\r\n"
    } else if searcher.cfg.line_term == 0 {
        b"\0"
    } else {
        b"\n"
    }
}

fn has_line_terminator(searcher: &Searcher, line: &[u8]) -> bool {
    line.last() == Some(&searcher.cfg.line_term)
}

fn trim_ascii_prefix(searcher: &Searcher, slice: &[u8], start: usize, end: usize) -> usize {
    let lt = searcher.cfg.line_term;
    let crlf = searcher.cfg.crlf;
    let mut s = start;
    while s < end {
        let b = slice[s];
        let is_space = matches!(b, b'\t' | b'\n' | b'\x0B' | b'\x0C' | b'\r' | b' ');
        let is_term = b == lt || (crlf && b == b'\r');
        if is_space && !is_term {
            s += 1;
        } else {
            break;
        }
    }
    s
}

/// Records the matches and the replacement for the current sink event.
fn record_matches(
    searcher: &Searcher,
    matcher: &Matcher,
    bytes: &[u8],
    start: usize,
    end: usize,
    out: &mut Vec<(usize, usize)>,
) {
    out.clear();
    find_iter_at_in_context(searcher, matcher, bytes, start, end, |s, e| {
        out.push((s - start, e - start));
        true
    });
    if let Some(&(s, e)) = out.last() {
        if s == e && s >= end - start {
            out.pop();
        }
    }
}

fn replace_all(
    searcher: &Searcher,
    matcher: &Matcher,
    bytes: &[u8],
    start: usize,
    end: usize,
    replacement: &[u8],
    dst: &mut Vec<u8>,
    matches: &mut Vec<(usize, usize)>,
) {
    dst.clear();
    matches.clear();
    let subject: &[u8] = if searcher.cfg.multi_line {
        if bytes.len() - end >= MAX_LOOK_AHEAD {
            &bytes[..end + MAX_LOOK_AHEAD]
        } else {
            bytes
        }
    } else {
        let e = trim_line_terminator_end(searcher, bytes, 0, end);
        &bytes[..e]
    };
    let mut last = start;
    matcher.captures_iter_at(subject, start, |caps| {
        let m = caps.get_match().unwrap();
        if m.start() >= end {
            return false;
        }
        dst.extend_from_slice(&subject[last..m.start()]);
        last = m.end();
        let s = dst.len();
        interpolate(matcher, caps, subject, replacement, dst);
        let e = dst.len();
        matches.push((s, e));
        true
    });
    let tail_end = std::cmp::min(end, bytes.len());
    if last < tail_end {
        dst.extend_from_slice(&bytes[last..tail_end]);
    }
}

// ---------------------------------------------------------------------------
// Standard printer

pub struct StandardSink<'a, 'o> {
    pub cfg: &'a StandardConfig,
    pub pp: &'a PathPrinter,
    pub out: Out<'o>,
    pub path: Option<Vec<u8>>,
    pub abs_path: Option<std::path::PathBuf>,
    pub matcher: &'a Matcher,
    pub needs_match_granularity: bool,
    pub match_count: u64,
    pub after_context_remaining: u64,
    pub binary_byte_offset: Option<u64>,
    pub matches: Vec<(usize, usize)>,
    pub replaced: Option<(Vec<u8>, Vec<(usize, usize)>)>,
    pub stats: Stats,
    pub start_time: Instant,
    pub total_written_before: usize,
    in_color_match: std::cell::Cell<bool>,
}

impl<'a, 'o> StandardSink<'a, 'o> {
    pub fn new(
        cfg: &'a StandardConfig,
        pp: &'a PathPrinter,
        out: Out<'o>,
        path: Option<Vec<u8>>,
        abs_path: Option<std::path::PathBuf>,
        matcher: &'a Matcher,
        total_written_before: usize,
    ) -> StandardSink<'a, 'o> {
        let needs_match_granularity = (out.color && !cfg.colors.matched.is_none())
            || cfg.column
            || cfg.replacement.is_some()
            || cfg.per_match
            || cfg.only_matching
            || cfg.stats;
        StandardSink {
            cfg,
            pp,
            out,
            path: if cfg.path { path } else { None },
            abs_path,
            matcher,
            needs_match_granularity,
            match_count: 0,
            after_context_remaining: 0,
            binary_byte_offset: None,
            matches: vec![],
            replaced: None,
            stats: Stats::default(),
            start_time: Instant::now(),
            total_written_before,
            in_color_match: std::cell::Cell::new(false),
        }
    }

    pub fn has_match(&self) -> bool {
        self.match_count > 0
    }

    fn match_more_than_limit(&self) -> bool {
        match self.cfg.max_matches {
            None => false,
            Some(limit) => self.match_count > limit,
        }
    }

    fn should_quit(&self) -> bool {
        let limit = match self.cfg.max_matches {
            None => return false,
            Some(l) => l,
        };
        if self.match_count < limit {
            return false;
        }
        self.after_context_remaining == 0
    }

    fn record(&mut self, searcher: &Searcher, bytes: &[u8], start: usize, end: usize) {
        self.matches.clear();
        if !self.needs_match_granularity {
            return;
        }
        record_matches(searcher, self.matcher, bytes, start, end, &mut self.matches);
    }

    fn replace(&mut self, searcher: &Searcher, bytes: &[u8], start: usize, end: usize) {
        self.replaced = None;
        if let Some(ref rep) = self.cfg.replacement {
            let mut dst = vec![];
            let mut ms = vec![];
            replace_all(searcher, self.matcher, bytes, start, end, rep, &mut dst, &mut ms);
            self.replaced = Some((dst, ms));
        }
    }

    // --- writing helpers

    fn write(&mut self, b: &[u8]) {
        self.out.write(b);
    }

    fn write_line_term(&mut self, searcher: &Searcher) {
        let lt = line_term_bytes(searcher);
        self.out.write(lt);
    }

    fn write_path(&mut self, path: &[u8]) {
        let disp = self.pp.display(path);
        let spec = self.cfg.colors.path.clone();
        self.out.write_spec(&spec, &disp);
    }

    fn write_path_hyperlink(&mut self, path: &[u8], line: Option<u64>, column: Option<u64>) {
        let link = self.hyperlink_start(line, column);
        self.write_path(path);
        if link {
            self.out.write(b"\x1b]8;;\x1b\\");
        }
    }

    fn hyperlink_start(&mut self, line: Option<u64>, column: Option<u64>) -> bool {
        if !self.out.color {
            return false;
        }
        let hl = match self.pp.hyperlink {
            None => return false,
            Some(ref h) => h,
        };
        let abs = match self.abs_path {
            None => return false,
            Some(ref p) => p,
        };
        let url = hl.format(abs, line, column);
        self.out.write(b"\x1b]8;;");
        self.out.write(&url);
        self.out.write(b"\x1b\\");
        true
    }

    fn write_search_prelude(&mut self) {
        if self.out.count() > 0 {
            return;
        }
        if let Some(ref sep) = self.cfg.separator_search {
            if self.total_written_before > 0 {
                let sep = sep.clone();
                self.write(&sep);
                self.write(b"\n");
            }
        }
        if self.cfg.heading {
            if let Some(path) = self.path.clone() {
                self.write_path_hyperlink(&path, None, None);
                match self.cfg.path_terminator {
                    Some(t) => self.write(&[t]),
                    None => self.out.write(b"\n"),
                }
            }
        }
    }

    fn write_prelude(
        &mut self,
        searcher: &Searcher,
        is_context: bool,
        abs_offset: u64,
        line_number: Option<u64>,
        column: Option<u64>,
    ) {
        let sep: Vec<u8> = if is_context {
            self.cfg.separator_field_context.clone()
        } else {
            self.cfg.separator_field_match.clone()
        };
        #[derive(PartialEq)]
        enum Next {
            None,
            Field,
            PathTerm,
        }
        let mut next = Next::None;
        let mut link_open = false;
        // Hyperlink handling: a link wraps the path and line number.
        if !self.cfg.heading {
            if self.path.is_some() {
                link_open = self.hyperlink_start(line_number, column);
            }
        } else if self.path.is_some() && self.pp.hyperlink.is_some() {
            link_open = self.hyperlink_start(line_number, column);
        }
        let write_sep = |s: &mut Self, next: &mut Next| {
            match *next {
                Next::None => {}
                Next::Field => s.out.write(&sep),
                Next::PathTerm => {
                    let t = s.cfg.path_terminator.unwrap();
                    s.out.write(&[t]);
                }
            }
            *next = Next::None;
        };
        if !self.cfg.heading {
            if let Some(path) = self.path.clone() {
                write_sep(self, &mut next);
                self.write_path(&path);
                next = if self.cfg.path_terminator.is_some() { Next::PathTerm } else { Next::Field };
            }
        }
        if self.cfg.line_number {
            if let Some(n) = line_number {
                write_sep(self, &mut next);
                let spec = self.cfg.colors.line.clone();
                self.out.write_spec(&spec, n.to_string().as_bytes());
                next = Next::Field;
            }
        }
        if link_open {
            self.out.write(b"\x1b]8;;\x1b\\");
        }
        if self.cfg.column {
            if let Some(c) = column {
                write_sep(self, &mut next);
                let spec = self.cfg.colors.column.clone();
                self.out.write_spec(&spec, c.to_string().as_bytes());
                next = Next::Field;
            }
        }
        if self.cfg.byte_offset {
            write_sep(self, &mut next);
            let spec = self.cfg.colors.column.clone();
            self.out.write_spec(&spec, abs_offset.to_string().as_bytes());
            next = Next::Field;
        }
        let _ = searcher;
        write_sep(self, &mut next);
    }

    fn exceeds_max_columns(&self, line: &[u8]) -> bool {
        self.cfg.max_columns.map_or(false, |m| line.len() as u64 > m)
    }

    fn start_color_match(&mut self) {
        if self.in_color_match.get() {
            return;
        }
        let spec = self.cfg.colors.matched.clone();
        if self.out.color {
            spec.write_start(self.out.buf);
        }
        self.in_color_match.set(true);
    }

    fn end_color_match(&mut self) {
        if !self.in_color_match.get() {
            return;
        }
        if self.out.color {
            ColorSpec::write_reset(self.out.buf);
        }
        self.in_color_match.set(false);
    }

    fn write_colored_matches(
        &mut self,
        searcher: &Searcher,
        bytes: &[u8],
        mut ls: usize,
        mut le: usize,
        matches: &[(usize, usize)],
        midx: &mut usize,
    ) {
        le = trim_line_terminator_end(searcher, bytes, ls, le);
        if self.cfg.trim_ascii {
            ls = trim_ascii_prefix(searcher, bytes, ls, le);
        }
        if matches.is_empty() {
            self.write(&bytes[ls..le]);
            return;
        }
        while ls < le {
            if matches[*midx].1 <= ls {
                if *midx + 1 < matches.len() {
                    *midx += 1;
                    continue;
                } else {
                    self.end_color_match();
                    self.write(&bytes[ls..le]);
                    break;
                }
            }
            let m = matches[*midx];
            if ls < m.0 {
                let upto = std::cmp::min(le, m.0);
                self.end_color_match();
                self.write(&bytes[ls..upto]);
                ls = upto;
            } else {
                let upto = std::cmp::min(le, m.1);
                self.start_color_match();
                self.write(&bytes[ls..upto]);
                ls = upto;
            }
        }
        self.end_color_match();
    }

    fn write_exceeded_line(
        &mut self,
        searcher: &Searcher,
        is_context: bool,
        bytes: &[u8],
        ls: usize,
        le: usize,
        matches: &[(usize, usize)],
        midx: &mut usize,
        original_matches_len: usize,
    ) {
        if self.cfg.max_columns_preview {
            let limit = self.cfg.max_columns.unwrap_or(0) as usize;
            let end = bytes[ls..le]
                .grapheme_indices()
                .map(|(_, end, _)| end)
                .take(limit)
                .last()
                .unwrap_or(0)
                + ls;
            self.write_colored_matches(searcher, bytes, ls, end, matches, midx);
            if matches.is_empty() {
                self.write(b" [... omitted end of long line]");
            } else {
                let remaining = matches.iter().filter(|m| m.0 >= end && m.0 < le).count();
                let tense = if remaining == 1 { "match" } else { "matches" };
                let s = format!(" [... {} more {}]", remaining, tense);
                self.write(s.as_bytes());
            }
            self.write_line_term(searcher);
            return;
        }
        if original_matches_len == 0 {
            if is_context {
                self.write(b"[Omitted long context line]");
            } else {
                self.write(b"[Omitted long matching line]");
            }
        } else if self.cfg.only_matching {
            if is_context {
                self.write(b"[Omitted long context line]");
            } else {
                self.write(b"[Omitted long matching line]");
            }
        } else {
            let s = format!("[Omitted long line with {} matches]", original_matches_len);
            self.write(s.as_bytes());
        }
        self.write_line_term(searcher);
    }

    fn write_line(&mut self, searcher: &Searcher, is_context: bool, line: &[u8], matches: &[(usize, usize)], orig_len: usize) {
        let line: &[u8] = if self.cfg.trim_ascii {
            let s = trim_ascii_prefix(searcher, line, 0, line.len());
            &line[s..]
        } else {
            line
        };
        if self.exceeds_max_columns(line) {
            let mut midx = 0;
            self.write_exceeded_line(searcher, is_context, line, 0, line.len(), matches, &mut midx, orig_len);
        } else {
            self.write(line);
            if !has_line_terminator(searcher, line) {
                self.write_line_term(searcher);
            }
        }
    }

    fn write_colored_line(&mut self, searcher: &Searcher, is_context: bool, matches: &[(usize, usize)], bytes: &[u8], orig_len: usize) {
        let spec_none = self.cfg.colors.matched.is_none();
        if !self.out.color || spec_none {
            return self.write_line(searcher, is_context, bytes, matches, orig_len);
        }
        if self.exceeds_max_columns(bytes) {
            let mut midx = 0;
            self.write_exceeded_line(searcher, is_context, bytes, 0, bytes.len(), matches, &mut midx, orig_len);
        } else {
            let mut midx = 0;
            self.write_colored_matches(searcher, bytes, 0, bytes.len(), matches, &mut midx);
            self.write_line_term(searcher);
        }
    }

    /// Print a sunk event.
    fn sink_impl(
        &mut self,
        searcher: &Searcher,
        is_context: bool,
        bytes: &[u8],
        matches: &[(usize, usize)],
        orig_len: usize,
        abs_offset: u64,
        line_number: Option<u64>,
    ) {
        self.write_search_prelude();
        let multi_line = searcher.cfg.multi_line;
        let lt = searcher.cfg.line_term;
        if matches.is_empty() {
            if multi_line && !is_context {
                let mut off = abs_offset;
                let mut i = 0u64;
                let mut s = 0;
                while s < bytes.len() {
                    let e = match memchr::memchr(lt, &bytes[s..]) {
                        Some(k) => s + k + 1,
                        None => bytes.len(),
                    };
                    self.write_prelude(searcher, is_context, off, line_number.map(|n| n + i), None);
                    off += (e - s) as u64;
                    self.write_line(searcher, is_context, &bytes[s..e], matches, orig_len);
                    i += 1;
                    s = e;
                }
            } else {
                self.write_prelude(searcher, is_context, abs_offset, line_number, None);
                self.write_line(searcher, is_context, bytes, matches, orig_len);
            }
            return;
        }
        if multi_line && !is_context {
            if self.cfg.only_matching {
                self.sink_slow_multi_line_only_matching(searcher, bytes, matches, abs_offset, line_number, orig_len);
            } else if self.cfg.per_match {
                self.sink_slow_multi_per_match(searcher, bytes, matches, abs_offset, line_number, orig_len);
            } else {
                let mut midx = 0;
                let mut count = 0u64;
                let mut s = 0;
                while s < bytes.len() {
                    let e = match memchr::memchr(lt, &bytes[s..]) {
                        Some(k) => s + k + 1,
                        None => bytes.len(),
                    };
                    self.write_prelude(
                        searcher,
                        is_context,
                        abs_offset + s as u64,
                        line_number.map(|n| n + count),
                        Some(matches[0].0 as u64 + 1),
                    );
                    count += 1;
                    if self.exceeds_max_columns(&bytes[s..e]) {
                        self.write_exceeded_line(searcher, is_context, bytes, s, e, matches, &mut midx, orig_len);
                    } else {
                        self.write_colored_matches(searcher, bytes, s, e, matches, &mut midx);
                        self.write_line_term(searcher);
                    }
                    s = e;
                }
            }
            return;
        }
        if self.cfg.only_matching {
            for &m in matches {
                self.write_prelude(searcher, is_context, abs_offset + m.0 as u64, line_number, Some(m.0 as u64 + 1));
                let buf = &bytes[m.0..m.1];
                self.write_colored_line(searcher, is_context, &[(0, buf.len())], buf, orig_len);
            }
        } else if self.cfg.per_match {
            for &m in matches {
                self.write_prelude(searcher, is_context, abs_offset + m.0 as u64, line_number, Some(m.0 as u64 + 1));
                self.write_colored_line(searcher, is_context, &[m], bytes, orig_len);
            }
        } else {
            self.write_prelude(searcher, is_context, abs_offset, line_number, Some(matches[0].0 as u64 + 1));
            self.write_colored_line(searcher, is_context, matches, bytes, orig_len);
        }
    }

    fn sink_slow_multi_line_only_matching(
        &mut self,
        searcher: &Searcher,
        bytes: &[u8],
        matches: &[(usize, usize)],
        abs_offset: u64,
        line_number: Option<u64>,
        orig_len: usize,
    ) {
        let lt = searcher.cfg.line_term;
        let spec = self.cfg.colors.matched.clone();
        let mut midx = 0;
        let mut count = 0u64;
        let mut s = 0;
        while s < bytes.len() {
            let e = match memchr::memchr(lt, &bytes[s..]) {
                Some(k) => s + k + 1,
                None => bytes.len(),
            };
            let mut ls = s;
            let mut le = trim_line_terminator_end(searcher, bytes, s, e);
            if self.cfg.trim_ascii {
                ls = trim_ascii_prefix(searcher, bytes, ls, le);
            }
            while ls < le {
                if matches[midx].1 <= ls {
                    if midx + 1 < matches.len() {
                        midx += 1;
                        continue;
                    } else {
                        break;
                    }
                }
                let m = matches[midx];
                if ls < m.0 {
                    let upto = std::cmp::min(le, m.0);
                    ls = upto;
                } else {
                    let upto = std::cmp::min(le, m.1);
                    self.write_prelude(
                        searcher,
                        false,
                        abs_offset + m.0 as u64,
                        line_number.map(|n| n + count),
                        Some(m.0 as u64 + 1),
                    );
                    let (ts, te) = (ls, upto);
                    ls = upto;
                    if self.exceeds_max_columns(&bytes[ts..te]) {
                        let mut z = 0;
                        self.write_exceeded_line(searcher, false, bytes, ts, te, &[m], &mut z, orig_len);
                    } else {
                        self.out.write_spec(&spec, &bytes[ts..te]);
                        self.write_line_term(searcher);
                    }
                }
            }
            let _ = &mut le;
            count += 1;
            s = e;
        }
    }

    fn sink_slow_multi_per_match(
        &mut self,
        searcher: &Searcher,
        bytes: &[u8],
        matches: &[(usize, usize)],
        abs_offset: u64,
        line_number: Option<u64>,
        orig_len: usize,
    ) {
        let lt = searcher.cfg.line_term;
        let spec = self.cfg.colors.matched.clone();
        for &m in matches {
            let mut count = 0u64;
            let mut s = 0;
            while s < bytes.len() {
                let e = match memchr::memchr(lt, &bytes[s..]) {
                    Some(k) => s + k + 1,
                    None => bytes.len(),
                };
                if s >= m.1 {
                    break;
                } else if e <= m.0 {
                    count += 1;
                    s = e;
                    continue;
                }
                self.write_prelude(
                    searcher,
                    false,
                    abs_offset + s as u64,
                    line_number.map(|n| n + count),
                    Some(m.0.saturating_sub(s) as u64 + 1),
                );
                count += 1;
                if self.exceeds_max_columns(&bytes[s..e]) {
                    let mut z = 0;
                    self.write_exceeded_line(searcher, false, bytes, s, e, &[m], &mut z, orig_len);
                    s = e;
                    continue;
                }
                let mut ls = s;
                let le = trim_line_terminator_end(searcher, bytes, s, e);
                if self.cfg.trim_ascii {
                    ls = trim_ascii_prefix(searcher, bytes, ls, le);
                }
                while ls < le {
                    if m.1 <= ls {
                        self.write(&bytes[ls..le]);
                        ls = le;
                    } else if ls < m.0 {
                        let upto = std::cmp::min(le, m.0);
                        self.write(&bytes[ls..upto]);
                        ls = upto;
                    } else {
                        let upto = std::cmp::min(le, m.1);
                        self.out.write_spec(&spec, &bytes[ls..upto]);
                        ls = upto;
                    }
                }
                self.write_line_term(searcher);
                if self.cfg.per_match_one_line {
                    break;
                }
                s = e;
            }
        }
    }

    fn write_binary_message(&mut self, searcher: &Searcher, offset: u64) {
        if self.match_count == 0 {
            return;
        }
        let bin = searcher.cfg.binary;
        let path = self.path.clone();
        if bin.is_quit() {
            if let Some(p) = path {
                self.write_path_hyperlink(&p, None, None);
                self.write(b": ");
            }
            let s = format!(
                "WARNING: stopped searching binary file after match (found \"{}\" byte around offset {})\n",
                byte_debug(bin.byte().unwrap()),
                offset
            );
            self.write(s.as_bytes());
        } else if bin.is_convert() {
            if let Some(p) = path {
                self.write_path_hyperlink(&p, None, None);
                self.write(b": ");
            }
            let s = format!(
                "binary file matches (found \"{}\" byte around offset {})\n",
                byte_debug(bin.byte().unwrap()),
                offset
            );
            self.write(s.as_bytes());
        }
    }
}

pub fn byte_debug(b: u8) -> String {
    match b {
        0 => "\\0".to_string(),
        b'\n' => "\\n".to_string(),
        b'\r' => "\\r".to_string(),
        b'\t' => "\\t".to_string(),
        b if b.is_ascii_graphic() || b == b' ' => (b as char).to_string(),
        b => format!("\\x{:02X}", b),
    }
}

impl<'a, 'o> Sink for StandardSink<'a, 'o> {
    fn begin(&mut self, _s: &Searcher) -> bool {
        self.start_time = Instant::now();
        self.match_count = 0;
        self.after_context_remaining = 0;
        self.binary_byte_offset = None;
        if self.cfg.max_matches == Some(0) {
            return false;
        }
        true
    }

    fn matched(&mut self, searcher: &Searcher, m: &SinkMatch) -> bool {
        self.match_count += 1;
        if self.match_more_than_limit() {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        } else {
            self.after_context_remaining = searcher.cfg.after as u64;
        }
        self.record(searcher, m.buffer, m.start, m.end);
        self.replace(searcher, m.buffer, m.start, m.end);
        if self.cfg.stats {
            self.stats.matches += self.matches.len() as u64;
            let lt = searcher.cfg.line_term;
            let bytes = m.bytes();
            let mut n = memchr::memchr_iter(lt, bytes).count() as u64;
            if !bytes.is_empty() && bytes.last() != Some(&lt) {
                n += 1;
            }
            self.stats.matched_lines += n;
        }
        if searcher.cfg.binary.is_convert() && self.binary_byte_offset.is_some() {
            return false;
        }
        let orig_len = self.matches.len();
        if let Some((dst, ms)) = self.replaced.take() {
            self.sink_impl(searcher, false, &dst, &ms, orig_len, m.absolute_byte_offset, m.line_number);
            self.replaced = Some((dst, ms));
        } else {
            let matches = std::mem::take(&mut self.matches);
            self.sink_impl(searcher, false, m.bytes(), &matches, orig_len, m.absolute_byte_offset, m.line_number);
            self.matches = matches;
        }
        !self.should_quit()
    }

    fn context(&mut self, searcher: &Searcher, c: &SinkContext) -> bool {
        self.matches.clear();
        self.replaced = None;
        if c.kind == ContextKind::After {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        }
        if searcher.cfg.invert {
            self.record(searcher, c.bytes, 0, c.bytes.len());
            self.replace(searcher, c.bytes, 0, c.bytes.len());
        }
        if searcher.cfg.binary.is_convert() && self.binary_byte_offset.is_some() {
            return false;
        }
        let orig_len = self.matches.len();
        if let Some((dst, ms)) = self.replaced.take() {
            self.sink_impl(searcher, true, &dst, &ms, orig_len, c.absolute_byte_offset, c.line_number);
        } else {
            let matches = std::mem::take(&mut self.matches);
            self.sink_impl(searcher, true, c.bytes, &matches, orig_len, c.absolute_byte_offset, c.line_number);
            self.matches = matches;
        }
        !self.should_quit()
    }

    fn context_break(&mut self, searcher: &Searcher) -> bool {
        if let Some(sep) = self.cfg.separator_context.clone() {
            self.write(&sep);
            self.write_line_term(searcher);
        }
        true
    }

    fn binary_data(&mut self, _s: &Searcher, offset: u64) -> bool {
        self.binary_byte_offset = Some(offset);
        true
    }

    fn finish(&mut self, searcher: &Searcher, byte_count: u64, binary_offset: Option<u64>) {
        if binary_offset.is_some() && self.binary_byte_offset.is_none() {
            self.binary_byte_offset = binary_offset;
        }
        if let Some(off) = self.binary_byte_offset {
            self.write_binary_message(searcher, off);
        }
        if self.cfg.stats {
            self.stats.elapsed += self.start_time.elapsed();
            self.stats.searches += 1;
            if self.match_count > 0 {
                self.stats.searches_with_match += 1;
            }
            self.stats.bytes_searched += byte_count;
            self.stats.bytes_printed += self.out.count() as u64;
        }
    }
}

// ---------------------------------------------------------------------------
// Summary printer

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SummaryKind {
    Count,
    CountMatches,
    PathWithMatch,
    PathWithoutMatch,
    Quiet,
}

impl SummaryKind {
    fn quit_early(&self) -> bool {
        matches!(self, SummaryKind::Quiet | SummaryKind::PathWithMatch | SummaryKind::PathWithoutMatch)
    }
}

#[derive(Clone)]
pub struct SummaryConfig {
    pub kind: SummaryKind,
    pub colors: ColorSpecs,
    pub path: bool,
    pub max_matches: Option<u64>,
    pub exclude_zero: bool,
    pub separator_field: Vec<u8>,
    pub path_terminator: Option<u8>,
    pub stats: bool,
}

pub struct SummarySink<'a, 'o> {
    pub cfg: &'a SummaryConfig,
    pub pp: &'a PathPrinter,
    pub out: Out<'o>,
    pub path: Option<Vec<u8>>,
    pub abs_path: Option<std::path::PathBuf>,
    pub matcher: &'a Matcher,
    pub match_count: u64,
    pub binary_byte_offset: Option<u64>,
    pub stats: Stats,
    pub start_time: Instant,
}

impl<'a, 'o> SummarySink<'a, 'o> {
    pub fn new(
        cfg: &'a SummaryConfig,
        pp: &'a PathPrinter,
        out: Out<'o>,
        path: Option<Vec<u8>>,
        abs_path: Option<std::path::PathBuf>,
        matcher: &'a Matcher,
    ) -> SummarySink<'a, 'o> {
        SummarySink {
            cfg,
            pp,
            out,
            path,
            abs_path,
            matcher,
            match_count: 0,
            binary_byte_offset: None,
            stats: Stats::default(),
            start_time: Instant::now(),
        }
    }

    pub fn has_match(&self) -> bool {
        match self.cfg.kind {
            SummaryKind::PathWithoutMatch => self.match_count == 0,
            _ => self.match_count > 0,
        }
    }

    fn should_quit(&self) -> bool {
        match self.cfg.max_matches {
            None => false,
            Some(l) => self.match_count >= l,
        }
    }

    fn write_path(&mut self, path: &[u8]) {
        let disp = self.pp.display(path);
        let link = if self.out.color {
            if let (Some(hl), Some(abs)) = (self.pp.hyperlink.as_ref(), self.abs_path.as_ref()) {
                let url = hl.format(abs, None, None);
                self.out.write(b"\x1b]8;;");
                self.out.write(&url);
                self.out.write(b"\x1b\\");
                true
            } else {
                false
            }
        } else {
            false
        };
        let spec = self.cfg.colors.path.clone();
        self.out.write_spec(&spec, &disp);
        if link {
            self.out.write(b"\x1b]8;;\x1b\\");
        }
    }

    fn write_path_line(&mut self, searcher: &Searcher) {
        if let Some(p) = self.path.clone() {
            self.write_path(&p);
            match self.cfg.path_terminator {
                Some(t) => self.out.write(&[t]),
                None => self.out.write(line_term_bytes(searcher)),
            }
        }
    }

    fn write_path_field(&mut self) {
        if let Some(p) = self.path.clone() {
            self.write_path(&p);
            match self.cfg.path_terminator {
                Some(t) => self.out.write(&[t]),
                None => {
                    let s = self.cfg.separator_field.clone();
                    self.out.write(&s)
                }
            }
        }
    }
}

impl<'a, 'o> Sink for SummarySink<'a, 'o> {
    fn begin(&mut self, _s: &Searcher) -> bool {
        self.start_time = Instant::now();
        self.match_count = 0;
        self.binary_byte_offset = None;
        if self.cfg.max_matches == Some(0) {
            return false;
        }
        true
    }

    fn matched(&mut self, searcher: &Searcher, m: &SinkMatch) -> bool {
        let is_multi_line = searcher.cfg.multi_line || self.cfg.kind == SummaryKind::CountMatches;
        let sink_match_count = if !self.cfg.stats && !is_multi_line {
            1
        } else {
            let mut count = 0u64;
            find_iter_at_in_context(searcher, self.matcher, m.buffer, m.start, m.end, |_, _| {
                count += 1;
                true
            });
            count
        };
        if is_multi_line {
            self.match_count += sink_match_count;
        } else {
            self.match_count += 1;
        }
        if self.cfg.stats {
            self.stats.matches += sink_match_count;
            let lt = searcher.cfg.line_term;
            let bytes = m.bytes();
            let mut n = memchr::memchr_iter(lt, bytes).count() as u64;
            if !bytes.is_empty() && bytes.last() != Some(&lt) {
                n += 1;
            }
            self.stats.matched_lines += n;
        } else if self.cfg.kind.quit_early() {
            return false;
        }
        !self.should_quit()
    }

    fn context(&mut self, _s: &Searcher, _c: &SinkContext) -> bool {
        true
    }

    fn context_break(&mut self, _s: &Searcher) -> bool {
        true
    }

    fn binary_data(&mut self, _s: &Searcher, offset: u64) -> bool {
        self.binary_byte_offset = Some(offset);
        true
    }

    fn finish(&mut self, searcher: &Searcher, byte_count: u64, binary_offset: Option<u64>) {
        if binary_offset.is_some() {
            self.binary_byte_offset = binary_offset;
        }
        if self.cfg.stats {
            self.stats.elapsed += self.start_time.elapsed();
            self.stats.searches += 1;
            if self.match_count > 0 {
                self.stats.searches_with_match += 1;
            }
            self.stats.bytes_searched += byte_count;
        }
        if self.binary_byte_offset.is_some() && searcher.cfg.binary.is_quit() {
            self.match_count = 0;
            return;
        }
        let show_count = !self.cfg.exclude_zero || self.match_count > 0;
        match self.cfg.kind {
            SummaryKind::Count | SummaryKind::CountMatches => {
                if show_count {
                    self.write_path_field();
                    let s = self.match_count.to_string();
                    self.out.write(s.as_bytes());
                    self.out.write(line_term_bytes(searcher));
                }
            }
            SummaryKind::PathWithMatch => {
                if self.match_count > 0 {
                    self.write_path_line(searcher);
                }
            }
            SummaryKind::PathWithoutMatch => {
                if self.match_count == 0 {
                    self.write_path_line(searcher);
                }
            }
            SummaryKind::Quiet => {}
        }
    }
}

