// JSON printer

pub fn json_escape(s: &str, out: &mut Vec<u8>) {
    out.push(b'"');
    for c in s.chars() {
        match c {
            '"' => out.extend_from_slice(b"\\\""),
            '\\' => out.extend_from_slice(b"\\\\"),
            '\n' => out.extend_from_slice(b"\\n"),
            '\r' => out.extend_from_slice(b"\\r"),
            '\t' => out.extend_from_slice(b"\\t"),
            '\x08' => out.extend_from_slice(b"\\b"),
            '\x0C' => out.extend_from_slice(b"\\f"),
            c if (c as u32) < 0x20 => {
                out.extend_from_slice(format!("\\u{:04x}", c as u32).as_bytes());
            }
            c => {
                let mut buf = [0u8; 4];
                out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            }
        }
    }
    out.push(b'"');
}

pub fn base64(data: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut s = String::new();
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | (b[2] as u32);
        s.push(T[(n >> 18) as usize & 63] as char);
        s.push(T[(n >> 12) as usize & 63] as char);
        if chunk.len() > 1 {
            s.push(T[(n >> 6) as usize & 63] as char);
        } else {
            s.push('=');
        }
        if chunk.len() > 2 {
            s.push(T[n as usize & 63] as char);
        } else {
            s.push('=');
        }
    }
    s
}

pub fn json_data(data: &[u8], out: &mut Vec<u8>) {
    match std::str::from_utf8(data) {
        Ok(s) => {
            out.extend_from_slice(b"{\"text\":");
            json_escape(s, out);
            out.push(b'}');
        }
        Err(_) => {
            out.extend_from_slice(b"{\"bytes\":\"");
            out.extend_from_slice(base64(data).as_bytes());
            out.extend_from_slice(b"\"}");
        }
    }
}

pub fn json_duration_struct(d: Duration, out: &mut Vec<u8>) {
    let s = format!(
        "{{\"secs\":{},\"nanos\":{},\"human\":\"{:0.6}s\"}}",
        d.as_secs(),
        d.subsec_nanos(),
        fractional_seconds(d)
    );
    out.extend_from_slice(s.as_bytes());
}

pub fn json_duration_sorted(d: Duration, out: &mut Vec<u8>) {
    let s = format!(
        "{{\"human\":\"{:0.6}s\",\"nanos\":{},\"secs\":{}}}",
        fractional_seconds(d),
        d.subsec_nanos(),
        d.as_secs()
    );
    out.extend_from_slice(s.as_bytes());
}

pub fn json_stats_struct(st: &Stats, out: &mut Vec<u8>) {
    out.extend_from_slice(b"{\"elapsed\":");
    json_duration_struct(st.elapsed, out);
    let s = format!(
        ",\"searches\":{},\"searches_with_match\":{},\"bytes_searched\":{},\"bytes_printed\":{},\"matched_lines\":{},\"matches\":{}}}",
        st.searches, st.searches_with_match, st.bytes_searched, st.bytes_printed, st.matched_lines, st.matches
    );
    out.extend_from_slice(s.as_bytes());
}

pub fn json_stats_sorted(st: &Stats, out: &mut Vec<u8>) {
    let s = format!("{{\"bytes_printed\":{},\"bytes_searched\":{},\"elapsed\":", st.bytes_printed, st.bytes_searched);
    out.extend_from_slice(s.as_bytes());
    json_duration_sorted(st.elapsed, out);
    let s = format!(
        ",\"matched_lines\":{},\"matches\":{},\"searches\":{},\"searches_with_match\":{}}}",
        st.matched_lines, st.matches, st.searches, st.searches_with_match
    );
    out.extend_from_slice(s.as_bytes());
}

pub struct JsonSink<'a, 'o> {
    pub out: Out<'o>,
    pub path: Vec<u8>,
    pub matcher: &'a Matcher,
    pub max_matches: Option<u64>,
    pub match_count: u64,
    pub after_context_remaining: u64,
    pub begin_printed: bool,
    pub stats: Stats,
    pub start_time: Instant,
    matches: Vec<(usize, usize)>,
}

impl<'a, 'o> JsonSink<'a, 'o> {
    pub fn new(out: Out<'o>, path: Vec<u8>, matcher: &'a Matcher, max_matches: Option<u64>) -> Self {
        JsonSink {
            out,
            path,
            matcher,
            max_matches,
            match_count: 0,
            after_context_remaining: 0,
            begin_printed: false,
            stats: Stats::default(),
            start_time: Instant::now(),
            matches: vec![],
        }
    }

    pub fn has_match(&self) -> bool {
        self.match_count > 0
    }

    fn match_more_than_limit(&self) -> bool {
        match self.max_matches {
            None => false,
            Some(l) => self.match_count > l,
        }
    }

    fn should_quit(&self) -> bool {
        let limit = match self.max_matches {
            None => return false,
            Some(l) => l,
        };
        if self.match_count < limit {
            return false;
        }
        self.after_context_remaining == 0
    }

    fn write_begin(&mut self) {
        if self.begin_printed {
            return;
        }
        let mut v = vec![];
        v.extend_from_slice(b"{\"type\":\"begin\",\"data\":{\"path\":");
        json_data(&self.path, &mut v);
        v.extend_from_slice(b"}}\n");
        self.out.write(&v);
        self.begin_printed = true;
    }

    fn write_lines_msg(&mut self, ty: &str, bytes: &[u8], line_number: Option<u64>, abs: u64, matches: &[(usize, usize)]) {
        let mut v = vec![];
        v.extend_from_slice(format!("{{\"type\":\"{}\",\"data\":{{\"path\":", ty).as_bytes());
        json_data(&self.path, &mut v);
        v.extend_from_slice(b",\"lines\":");
        json_data(bytes, &mut v);
        match line_number {
            Some(n) => v.extend_from_slice(format!(",\"line_number\":{}", n).as_bytes()),
            None => v.extend_from_slice(b",\"line_number\":null"),
        }
        v.extend_from_slice(format!(",\"absolute_offset\":{},\"submatches\":[", abs).as_bytes());
        for (i, &(s, e)) in matches.iter().enumerate() {
            if i > 0 {
                v.push(b',');
            }
            v.extend_from_slice(b"{\"match\":");
            json_data(&bytes[s..e], &mut v);
            v.extend_from_slice(format!(",\"start\":{},\"end\":{}}}", s, e).as_bytes());
        }
        v.extend_from_slice(b"]}}\n");
        self.out.write(&v);
    }
}

impl<'a, 'o> Sink for JsonSink<'a, 'o> {
    fn begin(&mut self, _s: &Searcher) -> bool {
        self.start_time = Instant::now();
        self.match_count = 0;
        self.after_context_remaining = 0;
        if self.max_matches == Some(0) {
            return false;
        }
        true
    }

    fn matched(&mut self, searcher: &Searcher, m: &SinkMatch) -> bool {
        self.write_begin();
        self.match_count += 1;
        if self.match_more_than_limit() {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        } else {
            self.after_context_remaining = searcher.cfg.after as u64;
        }
        let mut ms = std::mem::take(&mut self.matches);
        record_matches(searcher, self.matcher, m.buffer, m.start, m.end, &mut ms);
        self.stats.matches += ms.len() as u64;
        let lt = searcher.cfg.line_term;
        let bytes = m.bytes();
        let mut n = memchr::memchr_iter(lt, bytes).count() as u64;
        if !bytes.is_empty() && bytes.last() != Some(&lt) {
            n += 1;
        }
        self.stats.matched_lines += n;
        self.write_lines_msg("match", bytes, m.line_number, m.absolute_byte_offset, &ms);
        self.matches = ms;
        !self.should_quit()
    }

    fn context(&mut self, searcher: &Searcher, c: &SinkContext) -> bool {
        self.write_begin();
        if c.kind == ContextKind::After {
            self.after_context_remaining = self.after_context_remaining.saturating_sub(1);
        }
        let mut ms = std::mem::take(&mut self.matches);
        ms.clear();
        if searcher.cfg.invert {
            record_matches(searcher, self.matcher, c.bytes, 0, c.bytes.len(), &mut ms);
        }
        self.write_lines_msg("context", c.bytes, c.line_number, c.absolute_byte_offset, &ms);
        self.matches = ms;
        !self.should_quit()
    }

    fn context_break(&mut self, _s: &Searcher) -> bool {
        true
    }

    fn finish(&mut self, _searcher: &Searcher, byte_count: u64, binary_offset: Option<u64>) {
        if !self.begin_printed {
            return;
        }
        self.stats.elapsed += self.start_time.elapsed();
        self.stats.searches += 1;
        if self.match_count > 0 {
            self.stats.searches_with_match += 1;
        }
        self.stats.bytes_searched += byte_count;
        self.stats.bytes_printed += self.out.count() as u64;
