    ("vscodium", "vscodium://file{path}:{line}:{column}"),
];

impl HyperlinkFormat {
    pub fn parse(s: &str) -> Result<HyperlinkFormat, String> {
        let s = match ALIASES.iter().find(|(a, _)| *a == s) {
            Some((_, f)) => *f,
            None => s,
        };
        let pre = "invalid hyperlink format: ";
        if s.is_empty() {
            return Ok(HyperlinkFormat::default());
        }
        let mut parts = vec![];
        let mut text = vec![];
        let bytes = s.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if b == b'{' {
                if bytes.get(i + 1) == Some(&b'{') {
                    text.push(b'{');
                    i += 2;
                    continue;
                }
                let end = match s[i + 1..].find('}') {
                    Some(e) => i + 1 + e,
                    None => {
                        return Err(format!(
                            "{}unclosed variable: found '{{' without a corresponding '}}' following it",
                            pre
                        ))
                    }
                };
                let name = &s[i + 1..end];
                let part = match name {
                    "path" => Part::Path,
                    "line" => Part::Line,
                    "column" => Part::Column,
                    "host" => Part::Host,
                    "wslprefix" => Part::WslPrefix,
                    _ => {
                        return Err(format!(
                            "{}invalid hyperlink format variable: '{}', choose from: path, line, column, host, wslprefix",
                            pre, name
                        ))
                    }
                };
                if !text.is_empty() {
                    parts.push(Part::Text(std::mem::take(&mut text)));
                }
                parts.push(part);
                i = end + 1;
            } else if b == b'}' {
                if bytes.get(i + 1) == Some(&b'}') {
                    text.push(b'}');
                    i += 2;
                    continue;
                }
                return Err(format!(
                    "{}unopened variable: found '}}' without a corresponding '{{' preceding it",
                    pre
                ));
            } else {
                text.push(b);
                i += 1;
            }
        }
        if !text.is_empty() {
            parts.push(Part::Text(text));
        }
        if !parts.contains(&Part::Path) {
            return Err(format!(
                "{}at least a {{path}} variable is required in a hyperlink format, or otherwise use a valid alias: default, file, grep+, kitty, macvim, none, textmate, vscode, vscode-insiders, vscodium",
                pre
            ));
        }
        if parts.contains(&Part::Column) && !parts.contains(&Part::Line) {
            return Err(format!(
                "{}the hyperlink format contains a {{column}} variable, but no {{line}} variable is present",
                pre
            ));
        }
        // Validate the scheme.
        let first_text: Option<&Vec<u8>> = match parts.first() {
            Some(Part::Text(t)) => Some(t),
            _ => None,
        };
        let valid_scheme = match first_text {
            None => false,
            Some(t) => {
                match t.iter().position(|&b| b == b':') {
                    None => false,
                    Some(0) => false,
                    Some(p) => t[..p].iter().all(|&b| b.is_ascii_alphanumeric() || b == b'+' || b == b'-' || b == b'.'),
                }
            }
        };
        if !valid_scheme {
            return Err(format!(
                "{}the hyperlink format must start with a valid URL scheme, i.e., [0-9A-Za-z+-.]+:",
                pre
            ));
        }
        Ok(HyperlinkFormat { parts })
    }

    pub fn is_empty(&self) -> bool {
        self.parts.is_empty()
    }

    pub fn is_line_dependent(&self) -> bool {
        self.parts.contains(&Part::Line)
    }
}

#[derive(Clone, Debug)]
pub struct HyperlinkConfig {
    pub format: HyperlinkFormat,
    pub host: Option<String>,
    pub wsl_prefix: Option<String>,
}

fn encode_path(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(input.len());
    for &b in input {
        match b {
            b'0'..=b'9' | b'A'..=b'Z' | b'a'..=b'z' | b'/' | b':' | b'-' | b'.' | b'_' | b'~' | 128..=255 => out.push(b),
            _ => {
                const HEX: &[u8] = b"0123456789ABCDEF";
                out.push(b'%');
                out.push(HEX[(b >> 4) as usize]);
                out.push(HEX[(b & 0xF) as usize]);
            }
        }
    }
    out
}

impl HyperlinkConfig {
    pub fn format(&self, path: &Path, line: Option<u64>, column: Option<u64>) -> Vec<u8> {
        let mut out = vec![];
        let pb = crate::ignore::path_bytes(path);
        for part in &self.format.parts {
            match part {
                Part::Text(t) => out.extend_from_slice(t),
                Part::Path => out.extend_from_slice(&encode_path(pb)),
                Part::Line => out.extend_from_slice(line.unwrap_or(1).to_string().as_bytes()),
                Part::Column => out.extend_from_slice(column.unwrap_or(1).to_string().as_bytes()),
                Part::Host => {
                    if let Some(ref h) = self.host {
                        out.extend_from_slice(h.as_bytes());
                    }
                }
                Part::WslPrefix => {
                    if let Some(ref w) = self.wsl_prefix {
                        out.extend_from_slice(w.as_bytes());
                    }
                }
            }
        }
        out
    }
}

pub fn hostname(bin: Option<&Path>) -> Option<String> {
    if let Some(bin) = bin {
        if !bin.as_os_str().is_empty() {
            let out = std::process::Command::new(bin).output().ok()?;
            if !out.status.success() {
                return None;
            }
            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
            if s.is_empty() {
                return None;
            }
            return Some(s);
        }
    }
    let mut buf = vec![0u8; 256];
    let r = unsafe { libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
    if r != 0 {
        return None;
    }
    let n = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    Some(String::from_utf8_lossy(&buf[..n]).into_owned())
}
