//! Directory traversal.

use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::rc::Rc;

use crate::flags::{SortMode, SortModeKind};
use crate::ignore::{path_bytes, IgnoreDir, Shared};

pub struct WalkConfig {
    pub follow: bool,
    pub max_depth: Option<usize>,
    pub max_filesize: Option<u64>,
    pub one_file_system: bool,
    pub sort: Option<SortMode>,
    pub sequential: bool,
    pub skip: Option<(u64, u64)>,
}

#[derive(Clone, Debug)]
pub struct Subject {
    pub path: PathBuf,
    pub is_stdin: bool,
    pub explicit: bool,
}

pub enum Event {
    Subject(Subject),
    Error(String),
    IgnoreError(String),
}

pub fn io_err(e: &std::io::Error) -> String {
    crate::util::io_err_string(e)
}

struct Walker<'a, F: FnMut(Event) -> bool> {
    cfg: &'a WalkConfig,
    shared: &'a Shared,
    f: F,
    quit: bool,
}

struct Entry {
    path: PathBuf,
    name: Vec<u8>,
    is_dir: bool,
    is_file: bool,
    is_symlink: bool,
    dev: Option<u64>,
}

impl<'a, F: FnMut(Event) -> bool> Walker<'a, F> {
    fn emit(&mut self, ev: Event) {
        if self.quit {
            return;
        }
        if !(self.f)(ev) {
            self.quit = true;
        }
    }

    fn report_ignore_errors(&mut self, errs: Vec<String>) {
        for e in errs {
            self.emit(Event::IgnoreError(e));
        }
    }

    fn err_fmt(&self, path: &Path, e: &std::io::Error) -> String {
        if self.cfg.sequential {
            format!("{}: IO error for operation on {}: {}", path.display(), path.display(), io_err(e))
        } else {
            format!("{}: {}", path.display(), io_err(e))
        }
    }

    fn read_dir(&mut self, dir: &Path) -> Option<Vec<Entry>> {
        let rd = match std::fs::read_dir(dir) {
            Ok(rd) => rd,
            Err(e) => {
                let msg = self.err_fmt(dir, &e);
                self.emit(Event::Error(msg));
                return None;
            }
        };
        let mut out = vec![];
        for ent in rd {
            let ent = match ent {
                Ok(e) => e,
                Err(e) => {
                    let msg = self.err_fmt(dir, &e);
                    self.emit(Event::Error(msg));
                    continue;
                }
            };
            let name = path_bytes(Path::new(&ent.file_name())).to_vec();
            let path = dir.join(ent.file_name());
            let ft = match ent.file_type() {
                Ok(ft) => ft,
                Err(e) => {
                    let msg = self.err_fmt(&path, &e);
                    self.emit(Event::Error(msg));
                    continue;
                }
            };
            out.push(Entry {
                path,
                name,
                is_dir: ft.is_dir(),
                is_file: ft.is_file(),
                is_symlink: ft.is_symlink(),
                dev: None,
            });
        }
        if let Some(sort) = self.cfg.sort {
            if sort.kind == SortModeKind::Path && !sort.reverse {
                out.sort_by(|a, b| a.name.cmp(&b.name));
            }
        }
        Some(out)
    }

    /// Resolve symlinks (if following) and check for loops. Returns false if
    /// the entry should be skipped (an error was reported).
    fn resolve(&mut self, ent: &mut Entry, ancestors: &[(PathBuf, u64, u64)]) -> bool {
        if ent.is_symlink && self.cfg.follow {
            match std::fs::metadata(&ent.path) {
                Ok(md) => {
                    ent.is_dir = md.is_dir();
                    ent.is_file = md.is_file();
                    ent.dev = Some(md.dev());
                    if ent.is_dir {
                        let (dev, ino) = (md.dev(), md.ino());
                        for (apath, adev, aino) in ancestors.iter() {
                            if *adev == dev && *aino == ino {
                                let msg = format!(
                                    "File system loop found: {} points to an ancestor {}",
                                    ent.path.display(),
                                    apath.display()
                                );
                                self.emit(Event::Error(msg));
                                return false;
                            }
                        }
                    }
                }
                Err(e) => {
                    let msg = self.err_fmt(&ent.path, &e);
                    self.emit(Event::Error(msg));
                    return false;
                }
            }
        }
        true
    }

    fn should_skip(&mut self, ig: &IgnoreDir, ent: &Entry, root_dev: Option<u64>) -> bool {
        let m = ig.matched(self.shared, path_bytes(&ent.path), ent.is_dir);
        if m.is_ignore() {
            return true;
        }
        if !ent.is_dir {
            if let Some(max) = self.cfg.max_filesize {
                if let Ok(md) = std::fs::metadata(&ent.path) {
                    if md.len() > max {
                        return true;
                    }
                }
            }
        }
        if ent.is_dir && self.cfg.one_file_system {
            if let Some(rd) = root_dev {
                let dev = match ent.dev {
                    Some(d) => Some(d),
                    None => std::fs::symlink_metadata(&ent.path).ok().map(|m| m.dev()),
                };
                if let Some(d) = dev {
                    if d != rd {
                        return true;
                    }
                }
            }
        }
        false
    }

    fn is_skip_file(&self, path: &Path) -> bool {
        if let Some((dev, ino)) = self.cfg.skip {
            if let Ok(md) = std::fs::metadata(path) {
                return md.dev() == dev && md.ino() == ino;
            }
        }
        false
    }

    fn emit_file(&mut self, path: PathBuf, explicit: bool) {
        if self.is_skip_file(&path) {
            return;
        }
        self.emit(Event::Subject(Subject { path, is_stdin: false, explicit }));
    }

    fn walk_seq(&mut self, dir: &Path, depth: usize, ig: Rc<IgnoreDir>, ancestors: &mut Vec<(PathBuf, u64, u64)>, root_dev: Option<u64>) {
        if self.quit {
            return;
        }
        if let Some(max) = self.cfg.max_depth {
            if depth >= max {
                return;
            }
        }
        let entries = match self.read_dir(dir) {
            None => return,
            Some(e) => e,
        };
        for mut ent in entries {
            if self.quit {
                return;
            }
            if !self.resolve(&mut ent, ancestors) {
                continue;
            }
            if self.should_skip(&ig, &ent, root_dev) {
                continue;
            }
            if ent.is_dir {
                let mut errs = vec![];
                let child = ig.child(self.shared, &ent.path, &mut errs);
                self.report_ignore_errors(errs);
                let md = std::fs::metadata(&ent.path).ok();
                if let Some(md) = md {
                    ancestors.push((ent.path.clone(), md.dev(), md.ino()));
                    self.walk_seq(&ent.path, depth + 1, child, ancestors, root_dev);
                    ancestors.pop();
                } else {
                    self.walk_seq(&ent.path, depth + 1, child, ancestors, root_dev);
                }
            } else if ent.is_file {
                self.emit_file(ent.path, false);
            }
        }
    }

    fn walk_stack(&mut self, root: &Path, ig: Rc<IgnoreDir>, root_dev: Option<u64>) {
        struct Work {
            path: PathBuf,
            depth: usize,
            is_dir: bool,
            ig: Rc<IgnoreDir>,
            ancestors: Rc<Vec<(PathBuf, u64, u64)>>,
        }
        let root_anc = match std::fs::metadata(root) {
            Ok(md) => vec![(root.to_path_buf(), md.dev(), md.ino())],
            Err(_) => vec![],
        };
        // The root's ignore matcher has already been built.
        let mut stack: Vec<Work> = vec![];
        // Process root directory listing.
        let mut process_dir = |w: &mut Self, path: &Path, depth: usize, ig: Rc<IgnoreDir>, ancestors: Rc<Vec<(PathBuf, u64, u64)>>, stack: &mut Vec<Work>| {
            if let Some(max) = w.cfg.max_depth {
                if depth >= max {
                    return;
                }
            }
            let entries = match w.read_dir(path) {
                None => return,
                Some(e) => e,
            };
            for mut ent in entries {
                if w.quit {
                    return;
                }
                if !w.resolve(&mut ent, &ancestors) {
                    continue;
                }
                if w.should_skip(&ig, &ent, root_dev) {
                    continue;
                }
                if !ent.is_dir && !ent.is_file {
                    continue;
                }
                stack.push(Work {
                    path: ent.path,
                    depth: depth + 1,
                    is_dir: ent.is_dir,
                    ig: ig.clone(),
                    ancestors: ancestors.clone(),
                });
            }
        };
        process_dir(self, root, 0, ig, Rc::new(root_anc), &mut stack);
        while let Some(w) = stack.pop() {
            if self.quit {
                return;
            }
            if w.is_dir {
                let mut errs = vec![];
                let child = w.ig.child(self.shared, &w.path, &mut errs);
                self.report_ignore_errors(errs);
                let mut anc = (*w.ancestors).clone();
                if let Ok(md) = std::fs::metadata(&w.path) {
                    anc.push((w.path.clone(), md.dev(), md.ino()));
