            } else {
                self.emit_file(w.path, false);
            }
        }
    }
}

/// Walk all of the given paths, calling `f` for each event. If `f` returns
/// false, then walking stops.
pub fn walk<F: FnMut(Event) -> bool>(paths: &[PathBuf], cfg: &WalkConfig, shared: &Shared, f: F) {
    let mut w = Walker { cfg, shared, f, quit: false };
    if cfg.sequential {
        for p in paths {
            if w.quit {
                return;
            }
            if p.as_os_str() == "-" {
                w.emit(Event::Subject(Subject { path: p.clone(), is_stdin: true, explicit: true }));
                continue;
            }
            let md = match std::fs::metadata(p) {
                Ok(md) => md,
                Err(e) => {
                    // A broken symlink as a root is reported via lstat failure too.
                    let msg = w.err_fmt(p, &e);
                    w.emit(Event::Error(msg));
                    continue;
                }
            };
            if !md.is_dir() {
                w.emit_file(p.clone(), true);
                continue;
            }
            let mut errs = vec![];
            let ig = IgnoreDir::root(shared, p, &mut errs);
            w.report_ignore_errors(errs);
            let mut anc = vec![(p.clone(), md.dev(), md.ino())];
            w.walk_seq(p, 0, ig, &mut anc, Some(md.dev()));
        }
    } else {
        // Stat all roots first, reporting errors up front.
        let mut roots: Vec<(PathBuf, Option<std::fs::Metadata>)> = vec![];
        for p in paths {
            if p.as_os_str() == "-" {
                roots.push((p.clone(), None));
                continue;
            }
            match std::fs::metadata(p) {
                Ok(md) => roots.push((p.clone(), Some(md))),
                Err(e) => {
                    let msg = w.err_fmt(p, &e);
                    w.emit(Event::Error(msg));
                    if w.quit {
                        return;
                    }
                }
            }
        }
        for (p, md) in roots {
            if w.quit {
                return;
            }
            match md {
                None => w.emit(Event::Subject(Subject { path: p, is_stdin: true, explicit: true })),
                Some(md) => {
                    if !md.is_dir() {
                        w.emit_file(p, true);
                    } else {
                        let mut errs = vec![];
                        let ig = IgnoreDir::root(shared, &p, &mut errs);
                        w.report_ignore_errors(errs);
                        w.walk_stack(&p, ig, Some(md.dev()));
                    }
                }
            }
        }
    }
}
