                    let msg = w.err_fmt(p, &e);
                    w.emit(Event::Error(msg));
                    continue;
                }
            };
            if !md.is_dir() {
                w.emit_file(p.clone(), true);
                continue;
            }
            let mut errs = vec![];
            let ig = IgnoreDir::root(shared, p, &mut errs);
            w.report_ignore_errors(errs);
