            max_columns_preview: low.max_columns_preview,
            max_matches: max_count,
            column,
            byte_offset: low.byte_offset,
            trim_ascii: low.trim,
            separator_search: file_separator,
            separator_context: low.context_separator.clone(),
            separator_field_match: low.field_match_separator.clone(),
            separator_field_context: low.field_context_separator.clone(),
            path_terminator,
            line_number,
            stats,
        };

        let summary_kind = if quiet {
            SummaryKind::Quiet
        } else {
            match search_mode {
                SearchMode::Count => {
                    if only_matching {
                        SummaryKind::CountMatches
                    } else {
                        SummaryKind::Count
                    }
                }
                SearchMode::CountMatches => SummaryKind::CountMatches,
                SearchMode::FilesWithMatches => SummaryKind::PathWithMatch,
                SearchMode::FilesWithoutMatch => SummaryKind::PathWithoutMatch,
                _ => SummaryKind::Quiet,
            }
        };
        let summary_path = match summary_kind {
            SummaryKind::PathWithMatch | SummaryKind::PathWithoutMatch => true,
            _ => with_filename,
        };
        let summary = SummaryConfig {
            kind: summary_kind,
            colors,
            path: summary_path,
            max_matches: max_count,
            exclude_zero: !low.include_zero,
            separator_field: b":".to_vec(),
            path_terminator,
            stats,
        };

        let matcher_cfg = MatcherConfig {
            case_insensitive: low.case == CaseMode::Insensitive,
            smart_case: low.case == CaseMode::Smart,
            multi_line: low.multiline,
            dot_matches_new_line: low.multiline && low.multiline_dotall,
            crlf: low.crlf,
            line_terminator: if low.multiline { None } else { Some(line_term) },
            unicode: !low.no_unicode,
            word: low.boundary == Some(BoundaryMode::Word),
            line: low.boundary == Some(BoundaryMode::Line),
            fixed_strings: low.fixed_strings,
            size_limit: low.regex_size_limit,
            dfa_size_limit: low.dfa_size_limit,
        };

        // Types.
        let mut types = TypesBuilder::new();
        types.add_defaults();
        for tc in low.type_changes.iter() {
            match tc {
                TypeChange::Clear { name } => types.clear(name),
                TypeChange::Add { def } => types.add_def(def)?,
                TypeChange::Select { name } => types.select(name),
                TypeChange::Negate { name } => types.negate(name),
            }
        }

        let ignore_opts = IgnoreOpts {
            hidden: !low.hidden,
            ignore: !low.no_ignore_dot,
            parents: !low.no_ignore_parent,
            git_global: !low.no_ignore_vcs && !low.no_ignore_global,
            git_ignore: !low.no_ignore_vcs,
            git_exclude: !low.no_ignore_vcs && !low.no_ignore_exclude,
            require_git: !low.no_require_git,
            case_insensitive: low.ignore_file_case_insensitive,
            custom_names: if low.no_ignore_dot { vec![] } else { vec![".rgignore".to_string()] },
        };

        let pre_globs = if low.pre_glob.is_empty() {
            None
        } else {
            let cwd = std::env::current_dir().unwrap_or_default();
            Some(Override::build(&cwd, &low.pre_glob, &[], false).map_err(|e| e.to_string())?)
        };

        Ok(HiArgs {
            mode: low.mode,
            patterns,
            paths,
            implicit_path,
            is_one_file,
            matcher_cfg,
            color,
            stats,
            quiet,
            sequential,
            mmap,
            binary_implicit,
            binary_explicit,
            encoding: low.encoding.clone(),
            pre: low.pre.clone(),
            pre_globs,
            search_zip: low.search_zip,
            sort,
            line_term,
            crlf: low.crlf,
            invert: low.invert_match,
            before,
            after,
            passthru,
            stop_on_nonmatch: low.stop_on_nonmatch,
            multiline: low.multiline,
            line_number,
            search_mode,
            standard,
            summary,
            path_printer,
            max_count,
            no_messages: low.no_messages,
            no_ignore_messages: low.no_ignore_messages,
            follow: low.follow,
            max_depth: low.max_depth,
            max_filesize: low.max_filesize,
            one_file_system: low.one_file_system,
            ignore_opts,
            types,
            null: low.null,
            buffer: low.buffer,
            is_tty,
            low,
        })
    }

    pub fn build_matcher(&self) -> Result<Matcher, String> {
        if self.low.engine == EngineChoice::PCRE2 {
            return Err("PCRE2 is not available in this build of ripgrep".to_string());
        }
        Matcher::new(&self.patterns, &self.matcher_cfg).map_err(|e| match e {
            crate::matcher::BuildError::Msg(m) => m,
        })
    }

    /// Build the shared ignore state. Returns any ignore related errors that
    /// should be reported (but are not fatal).
    pub fn build_shared(&self) -> Result<(Shared, Vec<String>), String> {
        let cwd = std::env::current_dir().unwrap_or_default();
        let overrides = Override::build(&cwd, &self.low.globs, &self.low.iglobs, self.low.glob_case_insensitive)
            .map_err(|e| e.to_string())?;
        let types = self.types.build()?;
        let mut errs = vec![];
        let global = if self.ignore_opts.git_global {
            match crate::ignore::global_gitignore_path() {
                Some(p) => {
                    let mut b = GitignoreBuilder::new(std::path::Path::new(""));
                    b.case_insensitive = self.ignore_opts.case_insensitive;
                    if let Some(e) = b.add_file(&p, false) {
                        errs.push(e);
                    }
                    b.build()
                }
                None => Gitignore::empty(),
            }
        } else {
            Gitignore::empty()
        };
        let mut explicit = vec![];
        if !self.low.no_ignore_files {
            for p in self.low.ignore_file.iter() {
                let mut b = GitignoreBuilder::new(std::path::Path::new(""));
                b.case_insensitive = self.ignore_opts.case_insensitive;
                if let Some(e) = b.add_file(p, true) {
                    errs.push(e);
                }
                explicit.push(b.build());
            }
        }
        Ok((
            Shared { opts: self.ignore_opts.clone(), overrides, types, global, explicit },
            errs,
        ))
    }
}
