//! High level argument processing: turns low level flags into a fully
//! resolved configuration.

use std::path::PathBuf;

use crate::color::ColorSpecs;
use crate::flags::*;
use crate::ignore::{Gitignore, GitignoreBuilder, IgnoreOpts, Override, Shared, TypesBuilder};
use crate::matcher::{Matcher, MatcherConfig};
use crate::printer::{PathPrinter, StandardConfig, SummaryConfig, SummaryKind};
use crate::searcher::BinaryDetection;

pub struct HiArgs {
    pub mode: Mode,
    pub patterns: Vec<String>,
    pub paths: Vec<PathBuf>,
    pub implicit_path: bool,
    pub is_one_file: bool,
    pub matcher_cfg: MatcherConfig,
    pub color: bool,
    pub stats: bool,
    pub quiet: bool,
    pub sequential: bool,
    pub mmap: bool,
    pub binary_implicit: BinaryDetection,
    pub binary_explicit: BinaryDetection,
    pub encoding: EncodingMode,
    pub pre: Option<PathBuf>,
    pub pre_globs: Option<Override>,
    pub search_zip: bool,
    pub sort: Option<SortMode>,
    pub line_term: u8,
    pub crlf: bool,
    pub invert: bool,
    pub before: usize,
    pub after: usize,
    pub passthru: bool,
    pub stop_on_nonmatch: bool,
    pub multiline: bool,
    pub line_number: bool,
    pub search_mode: SearchMode,
    pub standard: StandardConfig,
    pub summary: SummaryConfig,
    pub path_printer: PathPrinter,
    pub max_count: Option<u64>,
    pub no_messages: bool,
    pub no_ignore_messages: bool,
    pub follow: bool,
    pub max_depth: Option<usize>,
    pub max_filesize: Option<u64>,
    pub one_file_system: bool,
    pub ignore_opts: IgnoreOpts,
    pub low: LowArgs,
    pub types: TypesBuilder,
    pub null: bool,
    pub buffer: BufferMode,
    pub is_tty: bool,
}

pub fn is_tty_stdout() -> bool {
    unsafe { libc::isatty(1) == 1 }
}

pub fn is_readable_stdin() -> bool {
    unsafe {
        if libc::isatty(0) == 1 {
            return false;
        }
        let mut st: libc::stat = std::mem::zeroed();
        if libc::fstat(0, &mut st) != 0 {
            return false;
        }
        let fmt = st.st_mode & libc::S_IFMT;
        fmt == libc::S_IFREG || fmt == libc::S_IFIFO || fmt == libc::S_IFSOCK
    }
}

fn read_pattern_file(path: &PathBuf) -> Result<Vec<String>, String> {
    let data = if path.as_os_str() == "-" {
        let mut v = vec![];
        use std::io::Read;
        std::io::stdin().read_to_end(&mut v).map_err(|e| format!("{}: {}", path.display(), e))?;
        v
    } else {
        std::fs::read(path).map_err(|e| format!("{}: {}", path.display(), e))?
    };
    let mut out = vec![];
    let mut lineno = 0;
    for line in data.split(|&b| b == b'\n') {
        lineno += 1;
        let _ = lineno;
        out.push(line);
    }
    // A trailing newline doesn't produce an extra empty pattern.
    if data.ends_with(b"\n") || data.is_empty() {
        out.pop();
    }
    let mut pats = vec![];
    for (i, line) in out.iter().enumerate() {
        let line = if line.ends_with(b"\r") { &line[..line.len() - 1] } else { line };
        match std::str::from_utf8(line) {
            Ok(s) => pats.push(s.to_string()),
            Err(_) => {
                return Err(format!(
                    "{}:{}: found invalid UTF-8 in pattern: {}",
                    path.display(),
                    i + 1,
                    crate::util::escape_bytes(line)
                ))
            }
        }
    }
    Ok(pats)
}

impl HiArgs {
    pub fn from_low(mut low: LowArgs) -> Result<HiArgs, String> {
        let is_tty = is_tty_stdout();
        // Patterns.
        let mut patterns: Vec<String> = vec![];
        let mut positional: Vec<std::ffi::OsString> = std::mem::take(&mut low.positional);
        let mut have_explicit_patterns = false;
        for p in low.patterns.iter() {
            have_explicit_patterns = true;
            match p {
                PatternSource::Regexp(s) => patterns.push(s.clone()),
                PatternSource::File(path) => {
                    let pats = read_pattern_file(path)?;
                    patterns.extend(pats);
                }
            }
        }
        let is_search = matches!(low.mode, Mode::Search(_));
        if is_search && !have_explicit_patterns {
            if positional.is_empty() {
                return Err("ripgrep requires at least one pattern to execute a search".to_string());
            }
            let p = positional.remove(0);
            match p.into_string() {
                Ok(s) => patterns.push(s),
                Err(os) => {
                    return Err(format!(
                        "pattern given is not valid UTF-8: {}",
                        crate::util::escape_bytes(crate::flags::os_bytes(&os))
                    ))
                }
            }
        }
        // Paths.
        let mut paths: Vec<PathBuf> = positional.into_iter().map(PathBuf::from).collect();
        let mut implicit_path = false;
        if paths.is_empty() {
            if is_search && is_readable_stdin() {
                paths.push(PathBuf::from("-"));
            } else {
                paths.push(PathBuf::from("./"));
                implicit_path = true;
            }
        }
        let is_one_file = paths.len() == 1 && (paths[0].as_os_str() == "-" || !paths[0].is_dir());
        let stdin_only = paths.len() == 1 && paths[0].as_os_str() == "-";

        let search_mode = match low.mode {
            Mode::Search(m) => m,
            _ => SearchMode::Standard,
        };
        let vimgrep = low.vimgrep;

        // Colors.
        let color = match low.color {
            ColorChoice::Never => false,
            ColorChoice::Always | ColorChoice::Ansi => true,
            ColorChoice::Auto => {
                let term_ok = match std::env::var_os("TERM") {
                    None => false,
                    Some(t) => t != "dumb",
                };
                let no_color = std::env::var_os("NO_COLOR").is_some();
                is_tty && term_ok && !no_color && !vimgrep
            }
        };

        let (before, after, passthru) = match low.context {
            ContextMode::Passthru => (0, 0, true),
            ref c => {
                let (b, a) = c.get();
                (b, a, false)
            }
        };

        let heading = if vimgrep { false } else { low.heading.unwrap_or(is_tty) };
        let with_filename = low.with_filename.unwrap_or(vimgrep || !is_one_file);
        let column = low.column.unwrap_or(vimgrep);
        let line_number = if search_mode == SearchMode::JSON {
            low.line_number.unwrap_or(true)
        } else if vimgrep {
            true
        } else {
            low.line_number.unwrap_or(column || (is_tty && !stdin_only))
        };

        let colors = ColorSpecs::new(&low.colors);
        let null_data = low.null_data;
        let line_term = if null_data { 0u8 } else { b'\n' };

        let binary = if null_data { BinaryMode::AsText } else { low.binary };
        let (binary_implicit, binary_explicit) = match binary {
            BinaryMode::Auto => (BinaryDetection::Quit(0), BinaryDetection::Convert(0)),
            BinaryMode::SearchAndSuppress => (BinaryDetection::Convert(0), BinaryDetection::Convert(0)),
            BinaryMode::AsText => (BinaryDetection::None, BinaryDetection::None),
        };

        let sort = low.sort;
        let sequential = low.threads == Some(1) || sort.is_some() || is_one_file;
        let mmap = match low.mmap {
            MmapMode::Never => false,
            MmapMode::AlwaysTryMmap => true,
            MmapMode::Auto => paths.len() <= 10 && paths.iter().all(|p| p.as_os_str() != "-" && p.is_file()),
        };

        let file_separator = if heading && search_mode == SearchMode::Standard {
            Some(b"".to_vec())
        } else if !passthru && (before > 0 || after > 0) {
            low.context_separator.clone()
        } else {
            None
        };

        let path_terminator = if low.null { Some(0u8) } else { None };
        let max_count = low.max_count;
        let only_matching = low.only_matching;
        let mut quiet = low.quiet;
        let stats = low.stats || search_mode == SearchMode::JSON;
        let _ = &mut quiet;

        let hyperlink_fmt = crate::hyperlink::HyperlinkFormat::parse(&low.hyperlink_format)
            .map_err(|e| e.to_string())?;
        let hyperlink = if hyperlink_fmt.is_empty() {
            None
        } else {
            let host = crate::hyperlink::hostname(low.hostname_bin.as_deref());
            let wsl_prefix = std::env::var("WSL_DISTRO_NAME").ok().map(|d| format!("wsl$/{}", d));
            Some(crate::hyperlink::HyperlinkConfig { format: hyperlink_fmt, host, wsl_prefix })
        };
        let path_printer = PathPrinter { separator: low.path_separator, hyperlink };

        let standard = StandardConfig {
            colors: colors.clone(),
            heading,
            path: with_filename,
            only_matching,
            per_match: vimgrep,
            per_match_one_line: vimgrep,
            replacement: low.replace.clone(),
            max_columns: low.max_columns,
            max_columns_preview: low.max_columns_preview,
            max_matches: max_count,
            column,
            byte_offset: low.byte_offset,
            trim_ascii: low.trim,
            separator_search: file_separator,
            separator_context: low.context_separator.clone(),
            separator_field_match: low.field_match_separator.clone(),
            separator_field_context: low.field_context_separator.clone(),
            path_terminator,
            line_number,
            stats,
        };

        let summary_kind = if quiet {
            SummaryKind::Quiet
        } else {
            match search_mode {
                SearchMode::Count => {
                    if only_matching {
                        SummaryKind::CountMatches
                    } else {
                        SummaryKind::Count
                    }
                }
                SearchMode::CountMatches => SummaryKind::CountMatches,
                SearchMode::FilesWithMatches => SummaryKind::PathWithMatch,
                SearchMode::FilesWithoutMatch => SummaryKind::PathWithoutMatch,
                _ => SummaryKind::Quiet,
            }
        };
        let summary_path = match summary_kind {
            SummaryKind::PathWithMatch | SummaryKind::PathWithoutMatch => true,
            _ => with_filename,
        };
        let summary = SummaryConfig {
            kind: summary_kind,
            colors,
            path: summary_path,
            max_matches: max_count,
            exclude_zero: !low.include_zero,
            separator_field: b":".to_vec(),
            path_terminator,
            stats,
        };

        let matcher_cfg = MatcherConfig {
            case_insensitive: low.case == CaseMode::Insensitive,
            smart_case: low.case == CaseMode::Smart,
            multi_line: low.multiline,
            dot_matches_new_line: low.multiline && low.multiline_dotall,
            crlf: low.crlf,
            line_terminator: if low.multiline { None } else { Some(line_term) },
            unicode: !low.no_unicode,
            word: low.boundary == Some(BoundaryMode::Word),
            line: low.boundary == Some(BoundaryMode::Line),
            fixed_strings: low.fixed_strings,
            size_limit: low.regex_size_limit,
            dfa_size_limit: low.dfa_size_limit,
        };

        // Types.
        let mut types = TypesBuilder::new();
        types.add_defaults();
        for tc in low.type_changes.iter() {
            match tc {
                TypeChange::Clear { name } => types.clear(name),
                TypeChange::Add { def } => types.add_def(def)?,
                TypeChange::Select { name } => types.select(name),
                TypeChange::Negate { name } => types.negate(name),
            }
        }

        let ignore_opts = IgnoreOpts {
            hidden: !low.hidden,
            ignore: !low.no_ignore_dot,
            parents: !low.no_ignore_parent,
            git_global: !low.no_ignore_vcs && !low.no_ignore_global,
            git_ignore: !low.no_ignore_vcs,
            git_exclude: !low.no_ignore_vcs && !low.no_ignore_exclude,
            require_git: !low.no_require_git,
            case_insensitive: low.ignore_file_case_insensitive,
            custom_names: if low.no_ignore_dot { vec![] } else { vec![".rgignore".to_string()] },
        };

        let pre_globs = if low.pre_glob.is_empty() {
            None
        } else {
            let cwd = std::env::current_dir().unwrap_or_default();
            Some(Override::build(&cwd, &low.pre_glob, &[], false).map_err(|e| e.to_string())?)
        };

        Ok(HiArgs {
            mode: low.mode,
            patterns,
            paths,
            implicit_path,
            is_one_file,
            matcher_cfg,
            color,
            stats,
            quiet,
            sequential,
            mmap,
            binary_implicit,
            binary_explicit,
            encoding: low.encoding.clone(),
            pre: low.pre.clone(),
            pre_globs,
            search_zip: low.search_zip,
            sort,
            line_term,
            crlf: low.crlf,
            invert: low.invert_match,
            before,
            after,
            passthru,
            stop_on_nonmatch: low.stop_on_nonmatch,
            multiline: low.multiline,
            line_number,
            search_mode,
            standard,
            summary,
            path_printer,
            max_count,
            no_messages: low.no_messages,
            no_ignore_messages: low.no_ignore_messages,
            follow: low.follow,
            max_depth: low.max_depth,
            max_filesize: low.max_filesize,
            one_file_system: low.one_file_system,
            ignore_opts,
            types,
            null: low.null,
            buffer: low.buffer,
            is_tty,
            low,
        })
    }

    pub fn build_matcher(&self) -> Result<Matcher, String> {
        if self.low.engine == EngineChoice::PCRE2 {
            return Err("PCRE2 is not available in this build of ripgrep".to_string());
        }
        Matcher::new(&self.patterns, &self.matcher_cfg).map_err(|e| match e {
            crate::matcher::BuildError::Msg(m) => m,
        })
    }

    /// Build the shared ignore state. Returns any ignore related errors that
    /// should be reported (but are not fatal).
    pub fn build_shared(&self) -> Result<(Shared, Vec<String>), String> {
        let cwd = std::env::current_dir().unwrap_or_default();
        let overrides = Override::build(&cwd, &self.low.globs, &self.low.iglobs, self.low.glob_case_insensitive)
            .map_err(|e| e.to_string())?;
        let types = self.types.build()?;
        let mut errs = vec![];
        let global = if self.ignore_opts.git_global {
            match crate::ignore::global_gitignore_path() {
                Some(p) => {
                    let mut b = GitignoreBuilder::new(std::path::Path::new(""));
                    b.case_insensitive = self.ignore_opts.case_insensitive;
                    if let Some(e) = b.add_file(&p, false) {
                        errs.push(e);
                    }
                    b.build()
                }
                None => Gitignore::empty(),
            }
        } else {
            Gitignore::empty()
        };
        let mut explicit = vec![];
        if !self.low.no_ignore_files {
            for p in self.low.ignore_file.iter() {
                let mut b = GitignoreBuilder::new(std::path::Path::new(""));
                b.case_insensitive = self.ignore_opts.case_insensitive;
                if let Some(e) = b.add_file(p, true) {
                    errs.push(e);
                }
                explicit.push(b.build());
            }
        }
        Ok((
            Shared { opts: self.ignore_opts.clone(), overrides, types, global, explicit },
            errs,
        ))
    }
}
