//! Top level search driver.

use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use crate::args::HiArgs;
use crate::encoding::Encoding;
use crate::flags::{EncodingMode, Mode, SearchMode, SortModeKind};
use crate::ignore::path_bytes;
use crate::matcher::Matcher;
use crate::printer::{JsonSink, Out, StandardSink, Stats, SummaryKind, SummarySink};
use crate::searcher::{BinaryDetection, Searcher, SearcherConfig};
use crate::walk::{Event, Subject, WalkConfig};

/// Stdout writer emulating block buffering.
struct Output {
    buf: Vec<u8>,
    cap: usize,
    direct: bool,
}

impl Output {
    fn write_chunk(&mut self, data: &[u8]) {
        if data.is_empty() {
            return;
        }
        if self.direct {
            self.flush();
            raw_write(data);
            return;
        }
        if self.buf.len() + data.len() > self.cap {
            self.flush();
        }
        if data.len() >= self.cap {
            raw_write(data);
        } else {
            self.buf.extend_from_slice(data);
        }
    }

    fn flush(&mut self) {
        if !self.buf.is_empty() {
            let b = std::mem::take(&mut self.buf);
            raw_write(&b);
        }
    }
}

fn raw_write(data: &[u8]) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    if let Err(e) = lock.write_all(data).and_then(|_| lock.flush()) {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            std::process::exit(0);
        }
        crate::eprint_msg(&e.to_string());
        std::process::exit(2);
    }
}

struct Ctx<'a> {
    args: &'a HiArgs,
    errored: bool,
}

impl<'a> Ctx<'a> {
    fn error(&mut self, msg: &str) {
        self.errored = true;
        if !self.args.no_messages {
            crate::eprint_msg(msg);
        }
    }
    fn ignore_error(&mut self, msg: &str) {
        if !self.args.no_messages && !self.args.no_ignore_messages {
            crate::eprint_msg(msg);
        }
    }
}

fn display_path(args: &HiArgs, subject: &Subject) -> Vec<u8> {
    if subject.is_stdin {
        return b"<stdin>".to_vec();
    }
    let b = path_bytes(&subject.path);
    if args.implicit_path {
        if let Some(rest) = b.strip_prefix(b"./") {
            return rest.to_vec();
        }
    }
    b.to_vec()
}

fn walk_config(args: &HiArgs) -> WalkConfig {
    let skip = unsafe {
        let mut st: libc::stat = std::mem::zeroed();
        if libc::fstat(1, &mut st) == 0 && (st.st_mode & libc::S_IFMT) == libc::S_IFREG {
            Some((st.st_dev as u64, st.st_ino as u64))
        } else {
            None
        }
    };
    WalkConfig {
        follow: args.follow,
        max_depth: args.max_depth,
        max_filesize: args.max_filesize,
        one_file_system: args.one_file_system,
        sort: args.sort,
        sequential: args.sequential,
        skip,
    }
}

/// Collect subjects, applying sorting if needed, then call `f` on each.
fn for_each_subject<F: FnMut(&mut Ctx, Subject) -> bool>(ctx: &mut Ctx, mut f: F) {
    let args = ctx.args;
    let cfg = walk_config(args);
    let shared = args.shared.as_ref().unwrap();
    let needs_collect = match args.sort {
        None => false,
        Some(s) => !(s.kind == SortModeKind::Path && !s.reverse),
    };
    if !needs_collect {
        crate::walk::walk(&args.paths, &cfg, shared, |ev| match ev {
            Event::Error(m) => {
                ctx.error(&m);
                true
            }
            Event::IgnoreError(m) => {
                ctx.ignore_error(&m);
                true
            }
            Event::Subject(s) => f(ctx, s),
        });
        return;
    }
    let mut subjects = vec![];
    crate::walk::walk(&args.paths, &cfg, shared, |ev| {
        match ev {
            Event::Error(m) => ctx.error(&m),
            Event::IgnoreError(m) => ctx.ignore_error(&m),
            Event::Subject(s) => subjects.push(s),
        }
        true
    });
    let sort = args.sort.unwrap();
    if sort.kind == SortModeKind::Path {
        subjects.sort_by(|a, b| a.path.cmp(&b.path).reverse());
    } else {
        let mut with_time: Vec<(Subject, Option<std::time::SystemTime>)> = subjects
            .into_iter()
            .map(|s| {
                let t = std::fs::metadata(&s.path).ok().and_then(|md| match sort.kind {
                    SortModeKind::LastModified => md.modified().ok(),
                    SortModeKind::LastAccessed => md.accessed().ok(),
                    SortModeKind::Created => md.created().ok(),
                    SortModeKind::Path => None,
                });
                (s, t)
            })
            .collect();
        with_time.sort_by(|(_, t1), (_, t2)| {
            use std::cmp::Ordering;
            let o = match (t1, t2) {
                (Some(a), Some(b)) => a.cmp(b),
                (Some(_), None) => Ordering::Less,
                (None, Some(_)) => Ordering::Greater,
                (None, None) => Ordering::Equal,
            };
            if sort.reverse {
                o.reverse()
            } else {
                o
            }
        });
        subjects = with_time.into_iter().map(|(s, _)| s).collect();
    }
    for s in subjects {
        if !f(ctx, s) {
            break;
        }
    }
}

pub fn run(args: HiArgs) -> i32 {
    let started = Instant::now();
    let mut ctx = Ctx { args: &args, errored: false };
    for e in args.ignore_errors.clone() {
        ctx.ignore_error(&e);
    }
    match args.mode {
        Mode::Types => {
            let mut out = vec![];
            for def in args.types.definitions() {
                if def.globs.is_empty() {
                    continue;
                }
                out.extend_from_slice(def.name.as_bytes());
                out.extend_from_slice(b": ");
                out.extend_from_slice(def.globs.join(", ").as_bytes());
                out.push(b'\n');
            }
            raw_write(&out);
            0
        }
        Mode::Files => run_files(&mut ctx),
        Mode::Search(_) => run_search(&mut ctx, started),
        Mode::Generate(_) => 0,
    }
}

fn run_files(ctx: &mut Ctx) -> i32 {
    let args = ctx.args;
    let mut output = Output { buf: vec![], cap: 8 * 1024, direct: !args.sequential };
    let mut matched = false;
    let quiet = args.quiet;
    let term: u8 = if args.null { 0 } else { b'\n' };
    let color = args.color;
    let spec = args.standard.colors.path.clone();
    let pp = args.path_printer.clone();
    for_each_subject(ctx, |_ctx, s| {
        matched = true;
        if quiet {
            return false;
        }
        let disp = display_path(args, &s);
        let disp = pp.display(&disp);
        let mut v = vec![];
        {
            let mut out = Out { buf: &mut v, color, start_len: 0 };
            out.write_spec(&spec, &disp);
        }
        v.push(term);
        output.write_chunk(&v);
        true
    });
    output.flush();
    if ctx.errored {
        if quiet && matched {
            0
        } else {
            2
        }
    } else if matched {
        0
    } else {
        1
    }
}

const DASHES: &str = "-------------------------------------------------------------------------------";

fn decompression_command(path: &Path) -> Option<Vec<String>> {
    let name = path.file_name()?.to_str()?;
    let table: &[(&[&str], &[&str])] = &[
        (&[".gz", ".tgz"], &["gzip", "-d", "-c"]),
        (&[".bz2", ".tbz2", ".tbz"], &["bzip2", "-d", "-c"]),
        (&[".xz", ".txz"], &["xz", "-d", "-c"]),
        (&[".lz4"], &["lz4", "-d", "-c"]),
        (&[".lzma"], &["xz", "--format=lzma", "-d", "-c"]),
        (&[".br"], &["brotli", "-d", "-c"]),
        (&[".zst", ".zstd"], &["zstd", "-q", "-d", "-c"]),
        (&[".Z"], &["uncompress", "-c"]),
    ];
    for (exts, cmd) in table {
        if exts.iter().any(|e| name.ends_with(e) && name.len() > 0) {
            // Make sure the program exists in PATH.
            if find_in_path(cmd[0]).is_none() {
                return None;
            }
            return Some(cmd.iter().map(|s| s.to_string()).collect());
        }
    }
    None
}

fn find_in_path(prog: &str) -> Option<PathBuf> {
    if prog.contains('/') {
        return Some(PathBuf::from(prog));
    }
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        let p = dir.join(prog);
        if let Ok(md) = std::fs::metadata(&p) {
            use std::os::unix::fs::PermissionsExt;
            if md.is_file() && md.permissions().mode() & 0o111 != 0 {
                return Some(p);
            }
        }
    }
    None
}

enum ReadErr {
    Msg(String),
}

fn run_command(mut cmd: std::process::Command, stdin_file: Option<std::fs::File>) -> std::io::Result<(Vec<u8>, Vec<u8>, bool)> {
    use std::process::Stdio;
    match stdin_file {
        Some(f) => {
            cmd.stdin(Stdio::from(f));
        }
        None => {
            cmd.stdin(Stdio::null());
        }
    }
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    let mut child = cmd.spawn()?;
    let mut stderr = child.stderr.take().unwrap();
    let errt = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = stderr.read_to_end(&mut v);
        v
    });
    let mut out = vec![];
    child.stdout.take().unwrap().read_to_end(&mut out)?;
    let status = child.wait()?;
    let err = errt.join().unwrap_or_default();
    Ok((out, err, status.success()))
}

/// Read the contents of a subject. Returns (data, is_regular_file_read).
fn read_subject(args: &HiArgs, subject: &Subject) -> Result<(Vec<u8>, bool), ReadErr> {
    if subject.is_stdin {
        let mut v = vec![];
        std::io::stdin().lock().read_to_end(&mut v).map_err(|e| ReadErr::Msg(e.to_string()))?;
        return Ok((v, false));
    }
    let path = &subject.path;
    if let Some(ref pre) = args.pre {
        let applies = match args.pre_globs {
            None => true,
            Some(ref ov) => {
                let m = ov.matched(path_bytes(path), false);
                !m.is_ignore()
            }
        };
        if applies {
            let file = std::fs::File::open(path).map_err(|e| ReadErr::Msg(e.to_string()))?;
            let mut cmd = std::process::Command::new(pre);
            cmd.arg(path);
            let desc = format!("'{:?} {:?}'", pre.as_os_str(), path.as_os_str());
            match run_command(cmd, Some(file)) {
                Err(e) => {
                    return Err(ReadErr::Msg(format!("preprocessor command could not start: {}: {}", desc, e)));
                }
                Ok((out, err, ok)) => {
                    if !ok {
                        let err = String::from_utf8_lossy(&err).into_owned();
                        return Err(ReadErr::Msg(format!(
                            "preprocessor command failed: {}: \n{}\n{}{}",
                            desc, DASHES, err, DASHES
                        )));
                    }
                    return Ok((out, false));
                }
            }
        }
    }
    if args.search_zip {
        if let Some(cmdv) = decompression_command(path) {
            let mut cmd = std::process::Command::new(&cmdv[0]);
            cmd.args(&cmdv[1..]);
            cmd.arg(path);
            match run_command(cmd, None) {
                Err(e) => return Err(ReadErr::Msg(e.to_string())),
                Ok((out, err, ok)) => {
                    if !ok {
                        let err = String::from_utf8_lossy(&err).into_owned();
                        return Err(ReadErr::Msg(format!("\n{}\n{}{}", DASHES, err, DASHES)));
                    }
                    return Ok((out, false));
                }
            }
        }
    }
    let mut f = std::fs::File::open(path).map_err(|e| ReadErr::Msg(e.to_string()))?;
    let md = f.metadata().ok();
    let mut v = Vec::with_capacity(md.as_ref().map(|m| m.len() as usize + 1).unwrap_or(0));
    f.read_to_end(&mut v).map_err(|e| ReadErr::Msg(e.to_string()))?;
    let regular = md.map(|m| m.is_file()).unwrap_or(false);
    Ok((v, regular))
}

fn run_search(ctx: &mut Ctx, started: Instant) -> i32 {
    let args = ctx.args;
    let matcher = match args.build_matcher() {
        Ok(m) => m,
        Err(e) => {
            crate::eprint_msg(&e);
            return 2;
        }
    };
    if args.max_count == Some(0) {
        // ripgrep doesn't search anything when no matches are possible.
        return if ctx.errored { 2 } else { 1 };
    }
    let multi_line = args.multiline && !matcher.never_matches_line_term;
    let mut output = Output { buf: vec![], cap: 8 * 1024, direct: !args.sequential };
    let mut matched = false;
    let mut searched = false;
    let mut total_stats = Stats::default();
    let mut total_written: usize = 0;
    let explicit_encoding: Option<Encoding> = match args.encoding {
        EncodingMode::Some(ref label) => Encoding::for_label(label.as_bytes()),
        _ => None,
    };
    let quit_after_match = args.quiet && !args.stats;
    for_each_subject(ctx, |ctx, subject| {
        searched = true;
        let disp = display_path(args, &subject);
        let (data, regular) = match read_subject(args, &subject) {
            Ok(d) => d,
            Err(ReadErr::Msg(m)) => {
                ctx.error(&format!("{}: {}", String::from_utf8_lossy(&disp), m));
                return true;
            }
        };
        let mut transcoded = false;
        let data = match args.encoding {
            EncodingMode::Disabled => data,
            EncodingMode::Auto => match crate::encoding::transcode(None, &data) {
                Some(d) => {
                    transcoded = true;
                    d
                }
                None => data,
            },
            EncodingMode::Some(_) => {
                transcoded = true;
                crate::encoding::transcode(explicit_encoding, &data).unwrap_or(data)
            }
        };
        let binary = if subject.explicit { args.binary_explicit } else { args.binary_implicit };
        let scfg = SearcherConfig {
            line_term: args.line_term,
            crlf: args.crlf,
            invert: args.invert,
            before: args.before,
            after: args.after,
            passthru: args.passthru,
            stop_on_nonmatch: args.stop_on_nonmatch,
            multi_line,
            binary,
            line_number: args.line_number && !matches!(args.search_mode, SearchMode::Count | SearchMode::CountMatches | SearchMode::FilesWithMatches | SearchMode::FilesWithoutMatch) && !args.quiet,
        };
        let searcher = Searcher::new(scfg, &matcher);
        let use_slice = multi_line || (args.mmap && regular && !transcoded);
        let abs_path = if args.path_printer.hyperlink.is_some() && !subject.is_stdin {
            std::fs::canonicalize(&subject.path).ok()
        } else {
            None
        };
        let mut buf: Vec<u8> = vec![];
        let (has_match, stats) = {
            let out = Out { buf: &mut buf, color: args.color, start_len: 0 };
            run_sink(args, &searcher, &matcher, out, disp.clone(), abs_path, data, use_slice, total_written)
        };
        if has_match {
            matched = true;
        }
        if let Some(st) = stats {
            total_stats.add(&st);
        }
        total_written += buf.len();
        output.write_chunk(&buf);
        if quit_after_match && has_match {
            return false;
        }
        true
    });
    if args.stats {
        let elapsed = started.elapsed();
        let mut v = vec![];
        if args.search_mode == SearchMode::JSON {
            v.extend_from_slice(b"{\"data\":{\"elapsed_total\":");
            crate::printer::json_duration_sorted(elapsed, &mut v);
            v.extend_from_slice(b",\"stats\":");
            crate::printer::json_stats_sorted(&total_stats, &mut v);
            v.extend_from_slice(b"},\"type\":\"summary\"}\n");
        } else {
            let s = format!(
                "\n{} matches\n{} matched lines\n{} files contained matches\n{} files searched\n{} bytes printed\n{} bytes searched\n{:0.6} seconds spent searching\n{:0.6} seconds\n",
                total_stats.matches,
                total_stats.matched_lines,
                total_stats.searches_with_match,
                total_stats.searches,
                total_stats.bytes_printed,
                total_stats.bytes_searched,
                crate::printer::fractional_seconds(total_stats.elapsed),
                crate::printer::fractional_seconds(elapsed),
            );
            v.extend_from_slice(s.as_bytes());
        }
        if !searched && args.implicit_path {
            // printed below
        }
        if !searched && args.implicit_path {
            output.flush();
            ctx.errored = true;
            if !args.no_messages {
                crate::eprint_msg("No files were searched, which means ripgrep probably applied a filter you didn't expect.\nRunning with --debug will show why files are being skipped.");
            }
        }
        output.write_chunk(&v);
        output.flush();
    } else {
        output.flush();
        if !searched && args.implicit_path {
            ctx.errored = true;
            if !args.no_messages {
                crate::eprint_msg("No files were searched, which means ripgrep probably applied a filter you didn't expect.\nRunning with --debug will show why files are being skipped.");
            }
        }
    }
    if matched && (args.quiet || !ctx.errored) {
        0
    } else if ctx.errored {
        2
    } else {
        1
    }
}

#[allow(clippy::too_many_arguments)]
fn run_sink(
    args: &HiArgs,
    searcher: &Searcher,
    matcher: &Matcher,
    out: Out,
    disp: Vec<u8>,
    abs_path: Option<PathBuf>,
    data: Vec<u8>,
    use_slice: bool,
    total_written: usize,
) -> (bool, Option<Stats>) {
    let quiet_or_summary = args.quiet
        || matches!(
            args.search_mode,
            SearchMode::Count | SearchMode::CountMatches | SearchMode::FilesWithMatches | SearchMode::FilesWithoutMatch
        );
    if args.search_mode == SearchMode::JSON {
        if args.quiet {
            let mut sink = SummarySink::new(&args.summary, &args.path_printer, out, Some(disp), abs_path, matcher);
            run_searcher(searcher, data, use_slice, &mut sink);
            return (sink.has_match(), None);
        }
        let mut sink = JsonSink::new(out, disp, matcher, args.max_count);
        run_searcher(searcher, data, use_slice, &mut sink);
        let st = sink.stats.clone();
        return (sink.has_match(), Some(st));
    }
    if quiet_or_summary {
        let path = if args.summary.path { Some(disp) } else { None };
        let mut sink = SummarySink::new(&args.summary, &args.path_printer, out, path, abs_path, matcher);
        run_searcher(searcher, data, use_slice, &mut sink);
        let st = if args.stats { Some(sink.stats.clone()) } else { None };
        let _ = SummaryKind::Quiet;
        return (sink.has_match(), st);
    }
    let mut sink = StandardSink::new(&args.standard, &args.path_printer, out, Some(disp), abs_path, matcher, total_written);
    run_searcher(searcher, data, use_slice, &mut sink);
    let st = if args.stats { Some(sink.stats.clone()) } else { None };
    (sink.has_match(), st)
}

fn run_searcher<S: crate::searcher::Sink>(searcher: &Searcher, data: Vec<u8>, use_slice: bool, sink: &mut S) {
    if use_slice {
        searcher.search_slice(&data, sink);
    } else {
        searcher.search_read(data, sink);
    }
    let _ = BinaryDetection::None;
}
