static LINE_BUFFER_CAP: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(BUFFER_CAPACITY);

struct LineBufSim {
    cap: usize,
    start: usize,
    end: usize,
    last_lineterm: usize,
    read_pos: usize,
    peek: bool,
    binary_offset: Option<usize>,
    binary: BinaryDetection,
    lt: u8,
}

impl LineBufSim {
    fn fill(&mut self, data: &mut [u8]) -> bool {
        if self.binary.is_quit() && self.binary_offset.is_some() {
            return self.start < self.last_lineterm;
        }
        loop {
            let occupancy = self.end - self.start;
            if occupancy >= self.cap {
                self.cap *= 3;
            }
            let request = self.cap - (self.end - self.start);
            let avail = data.len() - self.read_pos;
            let n = if self.peek && self.read_pos < 3 {
                std::cmp::min(std::cmp::min(request, 3 - self.read_pos), avail)
            } else {
                std::cmp::min(request, avail)
            };
            if n == 0 {
                self.last_lineterm = self.end;
                return self.start < self.end;
            }
            let (s, e) = (self.read_pos, self.read_pos + n);
            self.read_pos = e;
            self.end = e;
            match self.binary {
                BinaryDetection::None => {}
                BinaryDetection::Quit(b) => {
                    if let Some(i) = memchr::memchr(b, &data[s..e]) {
                        self.end = s + i;
                        self.last_lineterm = self.end;
                        self.binary_offset = Some(s + i);
                        return self.start < self.end;
                    }
                }
                BinaryDetection::Convert(b) => {
                    if b != self.lt {
                        let mut first = None;
                        for (k, x) in data[s..e].iter_mut().enumerate() {
                            if *x == b {
                                *x = self.lt;
                                if first.is_none() {
                                    first = Some(s + k);
                                }
                            }
                        }
                        if self.binary_offset.is_none() {
                            self.binary_offset = first;
                        }
                    }
                }
            }
            if let Some(i) = memchr::memrchr(self.lt, &data[s..e]) {
                self.last_lineterm = s + i + 1;
                return true;
            }
        }
    }
}

fn preceding(bytes: &[u8], lt: u8, mut count: usize) -> usize {
    let mut pos = bytes.len();
    if pos == 0 {
        return 0;
    }
    if bytes[pos - 1] == lt {
        pos -= 1;
    }
    loop {
        match memchr::memrchr(lt, &bytes[..pos]) {
            None => return 0,
            Some(i) => {
                if count == 0 {
                    return i + 1;
                } else if i == 0 {
                    return 0;
                }
                count -= 1;
                pos = i;
            }
        }
    }
}

