            i += 1;
            continue;
        }
        match st {
            St::Ascii => {
                if b == 0x0E || b == 0x0F || b >= 0x80 {
                    push(out, REPL);
                } else {
                    push(out, b as u32);
                }
                i += 1;
            }
            St::Roman => {
                if b == 0x5C {
                    push(out, 0xA5);
                } else if b == 0x7E {
                    push(out, 0x203E);
                } else if b == 0x0E || b == 0x0F || b >= 0x80 {
                    push(out, REPL);
                } else {
                    push(out, b as u32);
