//! Decoders for multi-byte CJK encodings following the WHATWG Encoding
//! Standard algorithms. Index tables are generated by tools/gen_cjk.py.

static JIS0208: &[u8] = include_bytes!("tables/jis0208.bin");
static JIS0212: &[u8] = include_bytes!("tables/jis0212.bin");
static EUCKR: &[u8] = include_bytes!("tables/euckr.bin");
static BIG5: &[u8] = include_bytes!("tables/big5.bin");
static GB18030: &[u8] = include_bytes!("tables/gb18030.bin");
static GB18030_RANGES: &[u8] = include_bytes!("tables/gb18030_ranges.bin");

fn lookup(table: &[u8], pointer: usize) -> Option<u32> {
    let i = pointer * 4;
    if i + 4 > table.len() {
        return None;
    }
    let v = u32::from_le_bytes([table[i], table[i + 1], table[i + 2], table[i + 3]]);
    if v == 0 {
        None
    } else {
        Some(v)
    }
}

fn push(out: &mut Vec<u8>, cp: u32) {
    let ch = char::from_u32(cp).unwrap_or('\u{FFFD}');
    let mut buf = [0u8; 4];
    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
}

const REPL: u32 = 0xFFFD;

fn shift_jis(input: &[u8], out: &mut Vec<u8>) {
    let mut lead: u8 = 0;
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        if lead != 0 {
            let l = lead;
            lead = 0;
            let offset = if b < 0x7F { 0x40 } else { 0x41 };
            let lead_offset = if l < 0xA0 { 0x81 } else { 0xC1 };
            let mut cp = None;
            if (0x40..=0x7E).contains(&b) || (0x80..=0xFC).contains(&b) {
                let pointer = (l as usize - lead_offset) * 188 + b as usize - offset;
                if (8836..=10715).contains(&pointer) {
                    cp = Some(0xE000 - 8836 + pointer as u32);
                } else {
                    cp = lookup(JIS0208, pointer);
                }
            }
            match cp {
                Some(c) => {
                    push(out, c);
                    i += 1;
                }
                None => {
                    push(out, REPL);
                    if b < 0x80 {
                        // reprocess
                    } else {
                        i += 1;
                    }
                }
            }
            continue;
        }
        if b < 0x80 || b == 0x80 {
            push(out, b as u32);
        } else if (0xA1..=0xDF).contains(&b) {
            push(out, 0xFF61 - 0xA1 + b as u32);
        } else if (0x81..=0x9F).contains(&b) || (0xE0..=0xFC).contains(&b) {
            lead = b;
        } else {
            push(out, REPL);
        }
        i += 1;
    }
    if lead != 0 {
        push(out, REPL);
    }
}

fn euc_jp(input: &[u8], out: &mut Vec<u8>) {
    let mut lead: u8 = 0;
    let mut jis0212 = false;
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        if lead == 0x8E && (0xA1..=0xDF).contains(&b) {
            lead = 0;
            push(out, 0xFF61 - 0xA1 + b as u32);
            i += 1;
            continue;
        }
        if lead == 0x8F && (0xA1..=0xFE).contains(&b) {
            jis0212 = true;
            lead = b;
            i += 1;
            continue;
        }
        if lead != 0 {
            let l = lead;
            lead = 0;
            let mut cp = None;
            if (0xA1..=0xFE).contains(&l) && (0xA1..=0xFE).contains(&b) {
                let pointer = (l as usize - 0xA1) * 94 + b as usize - 0xA1;
                cp = if jis0212 { lookup(JIS0212, pointer) } else { lookup(JIS0208, pointer) };
            }
            jis0212 = false;
            match cp {
                Some(c) => {
                    push(out, c);
                    i += 1;
                }
                None => {
                    push(out, REPL);
                    if b >= 0x80 {
                        i += 1;
                    }
                }
            }
            continue;
        }
        if b < 0x80 {
            push(out, b as u32);
        } else if b == 0x8E || b == 0x8F || (0xA1..=0xFE).contains(&b) {
            lead = b;
        } else {
            push(out, REPL);
        }
        i += 1;
    }
    if lead != 0 {
        push(out, REPL);
    }
}

fn euc_kr(input: &[u8], out: &mut Vec<u8>) {
    let mut lead: u8 = 0;
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        if lead != 0 {
            let l = lead;
            lead = 0;
            let mut cp = None;
            if (0x41..=0xFE).contains(&b) {
                let pointer = (l as usize - 0x81) * 190 + (b as usize - 0x41);
                cp = lookup(EUCKR, pointer);
            }
            match cp {
                Some(c) => {
