        if b < 0x80 {
            push(out, b as u32);
        } else if (0x81..=0xFE).contains(&b) {
            lead = b;
        } else {
            push(out, REPL);
        }
        i += 1;
    }
    if lead != 0 {
        push(out, REPL);
    }
}

fn big5(input: &[u8], out: &mut Vec<u8>) {
    let mut lead: u8 = 0;
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        if lead != 0 {
            let l = lead;
            lead = 0;
            let offset = if b < 0x7F { 0x40 } else { 0x62 };
            let mut pointer = None;
            if (0x40..=0x7E).contains(&b) || (0xA1..=0xFE).contains(&b) {
                pointer = Some((l as usize - 0x81) * 157 + (b as usize - offset));
            }
            match pointer {
                Some(1133) => {
                    push(out, 0xCA);
                    push(out, 0x304);
                    i += 1;
                    continue;
                }
                Some(1135) => {
                    push(out, 0xCA);
                    push(out, 0x30C);
                    i += 1;
                    continue;
                }
                Some(1164) => {
                    push(out, 0xEA);
                    push(out, 0x304);
                    i += 1;
                    continue;
                }
                Some(1166) => {
                    push(out, 0xEA);
                    push(out, 0x30C);
                    i += 1;
                    continue;
                }
                _ => {}
            }
            let cp = pointer.and_then(|p| lookup(BIG5, p));
            match cp {
                Some(c) => {
                    push(out, c);
                    i += 1;
                }
                None => {
                    push(out, REPL);
                    if b >= 0x80 {
                        i += 1;
                    }
                }
            }
            continue;
        }
        if b < 0x80 {
            push(out, b as u32);
        } else if (0x81..=0xFE).contains(&b) {
            lead = b;
        } else {
            push(out, REPL);
        }
        i += 1;
    }
    if lead != 0 {
        push(out, REPL);
    }
}

fn gb18030_range(pointer: usize) -> Option<u32> {
    if (pointer > 39419 && pointer < 189000) || pointer > 1237575 {
        return None;
    }
    if pointer == 7457 {
        return Some(0xE7C7);
    }
    if pointer >= 189000 {
        return Some(0x10000 + (pointer - 189000) as u32);
    }
    let n = GB18030_RANGES.len() / 8;
    let mut best: Option<(u32, u32)> = None;
    for k in 0..n {
        let o = k * 8;
        let p = u32::from_le_bytes([GB18030_RANGES[o], GB18030_RANGES[o + 1], GB18030_RANGES[o + 2], GB18030_RANGES[o + 3]]);
        let c = u32::from_le_bytes([GB18030_RANGES[o + 4], GB18030_RANGES[o + 5], GB18030_RANGES[o + 6], GB18030_RANGES[o + 7]]);
        if p as usize <= pointer {
            best = Some((p, c));
        } else {
            break;
        }
    }
    best.map(|(p, c)| c + (pointer as u32 - p))
}

fn gb18030(input: &[u8], out: &mut Vec<u8>) {
    let (mut first, mut second, mut third) = (0u8, 0u8, 0u8);
    let mut i = 0;
    // A queue of bytes to reprocess.
    let mut pending: Vec<u8> = vec![];
    loop {
        let b = if let Some(b) = pending.pop() {
            b
        } else if i < input.len() {
            i += 1;
            input[i - 1]
        } else {
            break;
        };
        if third != 0 {
            if !(0x30..=0x39).contains(&b) {
                push(out, REPL);
                pending.push(b);
                pending.push(third);
                pending.push(second);
                first = 0;
                second = 0;
                third = 0;
                continue;
            }
            let pointer = (((first as usize - 0x81) * 10 + second as usize - 0x30) * 126 + third as usize - 0x81) * 10
                + b as usize
                - 0x30;
            first = 0;
            second = 0;
            third = 0;
            match gb18030_range(pointer) {
                Some(c) => push(out, c),
                None => push(out, REPL),
            }
            continue;
        }
        if second != 0 {
            if (0x81..=0xFE).contains(&b) {
                third = b;
                continue;
            }
            push(out, REPL);
            pending.push(b);
            pending.push(second);
            first = 0;
            second = 0;
            continue;
        }
        if first != 0 {
            if (0x30..=0x39).contains(&b) {
                second = b;
                continue;
            }
            let l = first;
            first = 0;
            let offset = if b < 0x7F { 0x40 } else { 0x41 };
            let mut cp = None;
            if (0x40..=0x7E).contains(&b) || (0x80..=0xFE).contains(&b) {
                let pointer = (l as usize - 0x81) * 190 + (b as usize - offset);
                cp = lookup(GB18030, pointer);
            }
            match cp {
                Some(c) => push(out, c),
                None => {
                    push(out, REPL);
                    if b < 0x80 {
                        pending.push(b);
                    }
                }
            }
            continue;
        }
        if b < 0x80 {
            push(out, b as u32);
        } else if b == 0x80 {
            push(out, 0x20AC);
        } else if (0x81..=0xFE).contains(&b) {
            first = b;
        } else {
            push(out, REPL);
        }
    }
    if first != 0 || second != 0 || third != 0 {
        push(out, REPL);
    }
}

fn iso_2022_jp(input: &[u8], out: &mut Vec<u8>) {
    // A simplified ISO-2022-JP decoder.
    #[derive(PartialEq, Clone, Copy)]
    enum St {
        Ascii,
        Roman,
        Katakana,
        Lead,
    }
    let mut st = St::Ascii;
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        if b == 0x1B {
            let rest = &input[i + 1..];
            if rest.starts_with(b"(B") {
                st = St::Ascii;
                i += 3;
                continue;
            } else if rest.starts_with(b"(J") {
                st = St::Roman;
                i += 3;
                continue;
            } else if rest.starts_with(b"(I") {
                st = St::Katakana;
                i += 3;
                continue;
            } else if rest.starts_with(b"$@") || rest.starts_with(b"$B") {
                st = St::Lead;
                i += 3;
                continue;
            }
            push(out, REPL);
            i += 1;
            continue;
        }
        match st {
            St::Ascii => {
                if b == 0x0E || b == 0x0F || b >= 0x80 {
                    push(out, REPL);
                } else {
                    push(out, b as u32);
                }
                i += 1;
            }
            St::Roman => {
                if b == 0x5C {
                    push(out, 0xA5);
                } else if b == 0x7E {
                    push(out, 0x203E);
                } else if b == 0x0E || b == 0x0F || b >= 0x80 {
                    push(out, REPL);
                } else {
                    push(out, b as u32);
                }
                i += 1;
            }
            St::Katakana => {
                if (0x21..=0x5F).contains(&b) {
                    push(out, 0xFF61 - 0x21 + b as u32);
                } else if b == b'\n' {
                    push(out, b as u32);
                } else {
                    push(out, REPL);
                }
                i += 1;
            }
            St::Lead => {
                if b == b'\n' {
                    push(out, b as u32);
                    i += 1;
                    continue;
                }
                if (0x21..=0x7E).contains(&b) && i + 1 < input.len() && (0x21..=0x7E).contains(&input[i + 1]) {
                    let pointer = (b as usize - 0x21) * 94 + input[i + 1] as usize - 0x21;
                    match lookup(JIS0208, pointer) {
                        Some(c) => push(out, c),
                        None => push(out, REPL),
                    }
                    i += 2;
                } else {
                    push(out, REPL);
                    i += 1;
                }
            }
        }
    }
}

pub fn decode(name: &str, input: &[u8], out: &mut Vec<u8>) {
    match name {
        "Shift_JIS" => shift_jis(input, out),
        "EUC-JP" => euc_jp(input, out),
        "EUC-KR" => euc_kr(input, out),
        "Big5" => big5(input, out),
        "GBK" | "gb18030" => gb18030(input, out),
        "ISO-2022-JP" => iso_2022_jp(input, out),
        _ => {
            for &b in input {
                if b < 0x80 {
                    out.push(b);
                } else {
                    push(out, REPL);
                }
            }
        }
    }
}
