impl<'a> MarkedOut<'a> {
    pub fn new(out: &'a mut Vec<u8>, marks: &'a [usize]) -> MarkedOut<'a> {
        MarkedOut { out, marks, k: 0, rec: vec![], pos: 0 }
    }
    pub fn record(&mut self, upto: usize) {
        while self.k < self.marks.len() && self.marks[self.k] <= upto {
            self.rec.push(self.out.len());
            self.k += 1;
        }
    }
    pub fn finish(&mut self) {
        while self.k < self.marks.len() {
            self.rec.push(self.out.len());
            self.k += 1;
        }
    }
