fn decode_utf8(input: &[u8], out: &mut MarkedOut) {
    let mut i = 0;
    while i < input.len() {
        let b = input[i];
        out.pos = i;
        if b < 0x80 {
            push(out, b as u32);
            i += 1;
            continue;
        }
        // Determine the expected sequence length and valid second byte range.
        let (len, lo, hi) = match b {
            0xC2..=0xDF => (2, 0x80, 0xBF),
            0xE0 => (3, 0xA0, 0xBF),
            0xE1..=0xEC | 0xEE..=0xEF => (3, 0x80, 0xBF),
            0xED => (3, 0x80, 0x9F),
            0xF0 => (4, 0x90, 0xBF),
            0xF1..=0xF3 => (4, 0x80, 0xBF),
            0xF4 => (4, 0x80, 0x8F),
            _ => {
                push(out, 0xFFFD);
                i += 1;
                continue;
            }
        };
        let mut j = 1;
        let mut ok = true;
        while j < len {
            if i + j >= input.len() {
                ok = false;
                break;
            }
            let c = input[i + j];
            let (l, h) = if j == 1 { (lo, hi) } else { (0x80, 0xBF) };
            if c < l || c > h {
                ok = false;
                break;
            }
            j += 1;
        }
        if ok {
            out.pos = i + len - 1;
            let s = std::str::from_utf8(&input[i..i + len]).unwrap();
            let ch = s.chars().next().unwrap();
            push(out, ch as u32);
            i += len;
        } else {
            if i + j >= input.len() {
                // incomplete at EOF
                out.finish();
                out.out.extend_from_slice("\\u{FFFD}".as_bytes());
                return;
            }
            out.pos = i + j;
            push(out, 0xFFFD);
            i += j;
        }
    }
}

fn decode_utf16(input: &[u8], be: bool, out: &mut MarkedOut) {
    let mut i = 0;
    let mut pending_lead: Option<u16> = None;
    while i + 1 < input.len() {
        let u = if be {
            u16::from_be_bytes([input[i], input[i + 1]])
        } else {
            u16::from_le_bytes([input[i], input[i + 1]])
        };
        out.pos = i + 1;
        i += 2;
        if let Some(lead) = pending_lead.take() {
            if (0xDC00..0xE000).contains(&u) {
                let c = 0x10000 + (((lead as u32) - 0xD800) << 10) + ((u as u32) - 0xDC00);
                push(out, c);
                continue;
            } else {
                push(out, 0xFFFD);
            }
        }
        if (0xD800..0xDC00).contains(&u) {
            pending_lead = Some(u);
        } else if (0xDC00..0xE000).contains(&u) {
            push(out, 0xFFFD);
        } else {
            push(out, u as u32);
        }
    }
    out.finish();
    if pending_lead.is_some() {
        out.out.extend_from_slice("\\u{FFFD}".as_bytes());
    }
    if i < input.len() {
        out.out.extend_from_slice("\\u{FFFD}".as_bytes());
    }
}

/// Decode the given bytes using the given encoding, producing UTF-8. The
/// output offsets corresponding to the given input marks are also returned.
pub fn decode_marked(enc: Encoding, input: &[u8], marks: &[usize]) -> (Vec<u8>, Vec<usize>) {
    let mut buf = Vec::with_capacity(input.len());
    let rec = {
        let mut out = MarkedOut::new(&mut buf, marks);
        match enc {
            Encoding::Utf8 => decode_utf8(input, &mut out),
            Encoding::Utf16Le => decode_utf16(input, false, &mut out),
            Encoding::Utf16Be => decode_utf16(input, true, &mut out),
            Encoding::UserDefined => {
                for (i, &b) in input.iter().enumerate() {
                    out.pos = i;
                    if b < 0x80 {
                        push(&mut out, b as u32);
                    } else {
