                i += 1;
                continue;
            }
        };
        let mut j = 1;
        let mut ok = true;
        while j < len {
            if i + j >= input.len() {
                ok = false;
                break;
            }
            let c = input[i + j];
            let (l, h) = if j == 1 { (lo, hi) } else { (0x80, 0xBF) };
            if c < l || c > h {
                ok = false;
                break;
            }
            j += 1;
        }
        if ok {
            out.pos = i + len - 1;
            let s = std::str::from_utf8(&input[i..i + len]).unwrap();
            let ch = s.chars().next().unwrap();
            push(out, ch as u32);
            i += len;
        } else {
            if i + j >= input.len() {
                // incomplete at EOF
                out.finish();
                out.out.extend_from_slice("\\u{FFFD}".as_bytes());
                return;
            }
            out.pos = i + j;
            push(out, 0xFFFD);
            i += j;
        }
